task.spawn(function()
    repeat task.wait() until game:IsLoaded()
    
    -- ============================================================
    -- PC EXECUTOR COMPATIBILITY LAYER (Real / Maduim)
    -- Optional executor APIs are detected at runtime; missing APIs
    -- must never prevent the core GUI from loading.
    -- ============================================================
    
    -- ============================================================
    -- VISION.GG INTRO ANIMATION - CINEMATIC UPGRADE (10s duration)
    -- WITH EXTERNAL MP3 SOUND + CUSTOM BACKGROUND IMAGE (100137217709081)
    -- ============================================================
    
    local MUSIC_URL = "https://files.catbox.moe/tktp6l.mp3"
    local MUSIC_FILE = "AMIRI_Intro_tktp6l.mp3"
    local MUSIC_START = 10
    local MUSIC_VOLUME = 0.55
    
    -- Shared background list used by BOTH the main GUI and the intro.
    -- Background Image Selection #1-#10 (shared by MAIN GUI + INTRO)
    local BACKGROUND_IMAGES = {
        "90631990302263",
        "109619268613730",
        "88369503310562",
        "80708025126373",
        "102253425322931",
        "97295992542176",
        "107278609962886",
        "92297222888545",
        "84555602205234",
        "95541184611569",
        "96005510156373",
        "71758762621906",
        "73210580811131",
    }
    
    -- GUI COLOR OPTIONS
    local GUI_COLOR_ORDER = {"Blue", "Black", "White", "Purple", "Pink", "Red", "Yellow", "Orange"}
    local GUI_COLORS = {
        Blue   = Color3.fromRGB(45, 135, 255),
        Black  = Color3.fromRGB(20, 20, 20),
        White  = Color3.fromRGB(255, 255, 255),
        Purple = Color3.fromRGB(155, 75, 255),
        Pink   = Color3.fromRGB(255, 75, 170),
        Red    = Color3.fromRGB(255, 55, 55),
        Yellow = Color3.fromRGB(255, 210, 45),
        Orange = Color3.fromRGB(255, 125, 35),
    }
    local CURRENT_GUI_COLOR_NAME = "White"
    local CURRENT_GUI_COLOR = GUI_COLORS[CURRENT_GUI_COLOR_NAME]
    local _themeObjects = {}
    
    local function registerThemeObject(obj, kind)
        if obj then
            table.insert(_themeObjects, {object = obj, kind = kind or "stroke"})
        end
        return obj
    end
    
    local function applyGuiColor(color, colorName)
        if colorName and GUI_COLORS[colorName] then
            CURRENT_GUI_COLOR_NAME = colorName
            CURRENT_GUI_COLOR = GUI_COLORS[colorName]
        else
            CURRENT_GUI_COLOR = color
        end
    
        for _, entry in ipairs(_themeObjects) do
            local obj = entry.object
            if obj and obj.Parent then
                pcall(function()
                    if entry.kind == "stroke" and obj:IsA("UIStroke") then
                        obj.Color = CURRENT_GUI_COLOR
                    elseif entry.kind == "line" and obj:IsA("GuiObject") then
                        obj.BackgroundColor3 = CURRENT_GUI_COLOR
                    elseif entry.kind == "text" and (obj:IsA("TextLabel") or obj:IsA("TextButton")) then
                        obj.TextColor3 = CURRENT_GUI_COLOR
                    end
                end)
            end
        end
    end
    
    
    local function getSavedBackgroundId()
        local index = 1
        pcall(function()
            if type(isfile) == "function" and type(readfile) == "function" and isfile("Amiri.json") then
                local raw = readfile("Amiri.json")
                local data = game:GetService("HttpService"):JSONDecode(raw)
                index = tonumber(data and data.backgroundImageIndex) or 1
            end
        end)
        if index < 1 or index > #BACKGROUND_IMAGES then index = 1 end
        return BACKGROUND_IMAGES[index]
    end
    
    local function playIntroSound()
        -- PC executor safe: filesystem/custom-asset APIs are optional.
        -- If they are unavailable, simply skip the intro music instead of
        -- stopping the entire script before the GUI appears.
        if type(isfile) ~= "function" or type(readfile) ~= "function"
            or type(writefile) ~= "function" or type(getcustomasset) ~= "function" then
            return nil
        end
    
        local okFile, exists = pcall(isfile, MUSIC_FILE)
        if not okFile or not exists then
            local ok, data = pcall(game.HttpGet, game, MUSIC_URL)
            if not (ok and type(data) == "string" and #data > 1000) then
                return nil
            end
            local okWrite = pcall(writefile, MUSIC_FILE, data)
            if not okWrite then
                return nil
            end
        end
    
        local parent = game:GetService("CoreGui")
        if type(gethui) == "function" then
            local okHui, hui = pcall(gethui)
            if okHui and hui then parent = hui end
        end
    
        local okAsset, asset = pcall(getcustomasset, MUSIC_FILE)
        if not okAsset or type(asset) ~= "string" or asset == "" then
            return nil
        end
    
        local sound = Instance.new("Sound")
        sound.Name = "AMIRI_IntroMusic"
        sound.Parent = parent
        sound.SoundId = asset
        sound.Volume = MUSIC_VOLUME
        sound.Looped = false
        sound.TimePosition = MUSIC_START
        pcall(function() sound:Play() end)
        return sound
    end
    
    local function playIntroAnimation(onComplete)
        local Tw = game:GetService("TweenService")
        local Sg = game:GetService("StarterGui")
        local pr = game:GetService("Players").LocalPlayer
        local pg = pr:WaitForChild("PlayerGui")
        local D = 10.0
        
        local Silver1 = Color3.fromRGB(255, 255, 255)
        local Silver2 = Color3.fromRGB(200, 200, 200)
        local Silver3 = Color3.fromRGB(150, 150, 150)
    
        local introBlur
        local introSound = nil
    
        local function tn(i, t, st, dr, pr2)
            return Tw:Create(i, TweenInfo.new(t, st, dr), pr2)
        end
    
        pcall(function() Sg:SetCore("TopbarEnabled", false) end)
        local function uf() pcall(function() Sg:SetCore("TopbarEnabled", true) end) end
    
        local ex = pg:FindFirstChild("VISION_GG_Intro")
        if ex then ex:Destroy() end
    
        local gui = Instance.new("ScreenGui")
        gui.Name = "VISION_GG_Intro"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 1000
        gui.Parent = pg
        
        local introActive = true
        local introCompleted = false
    
        -- BACKGROUND IMAGE SA INTRO (New Asset ID)
        local bgImageIntro = Instance.new("ImageLabel", gui)
        bgImageIntro.Size = UDim2.new(1, 0, 1, 0)
        bgImageIntro.BackgroundTransparency = 0
        bgImageIntro.Image = "rbxassetid://" .. getSavedBackgroundId()  -- Uses selected background
        bgImageIntro.ImageTransparency = 0
        bgImageIntro.ScaleType = Enum.ScaleType.Crop
        bgImageIntro.ZIndex = 1
    
        -- dark overlay para readable ang text
        local overlay = Instance.new("Frame", gui)
        overlay.Size = UDim2.new(1, 0, 1, 0)
        overlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        overlay.BackgroundTransparency = 0.45  -- Mas kita ang image
        overlay.BorderSizePixel = 0
        overlay.ZIndex = 2
        tn(overlay, 0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, { BackgroundTransparency = 0.45 }):Play()
    
        -- SKIP BUTTON
        local skipBtn = Instance.new("TextButton", gui)
        skipBtn.Size = UDim2.new(0, 130, 0, 38)
        skipBtn.Position = UDim2.new(1, -160, 0, 20)
        skipBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        skipBtn.BackgroundTransparency = 0.85
        skipBtn.BorderSizePixel = 0
        skipBtn.Text = "SKIP INTRO"
        skipBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        skipBtn.TextTransparency = 1
        skipBtn.Font = Enum.Font.GothamBold
        skipBtn.TextSize = 13
        skipBtn.ZIndex = 50
        skipBtn.AutoButtonColor = false
        skipBtn.ClipsDescendants = false
