            tn(skipBtn, 0.05, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {BackgroundTransparency = 0.55}):Play()
        end)
    
        skipBtn.MouseButton1Click:Connect(function()
            if not introActive then return end
            introActive = false
            introCompleted = true
    
            if introSound then
                introSound:Stop()
                introSound:Destroy()
                introSound = nil
            end
    
            tn(skipBtn, 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {
                TextTransparency = 1, BackgroundTransparency = 1,
            }):Play()
            tn(skipStroke, 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {Transparency = 1}):Play()
            tn(skipArrow, 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {TextTransparency = 1}):Play()
            if introBlur then
                tn(introBlur, 0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {Size = 0}):Play()
            end
            task.delay(0.2, function()
                pcall(function()
                    if introBlur and introBlur.Parent then introBlur:Destroy() end
                end)
                pcall(function()
                    if gui and gui.Parent then gui:Destroy() end
                end)
                uf()
                if onComplete then onComplete() end
            end)
        end)
    
        -- Blur
        local Lighting = game:GetService("Lighting")
        local existingBlur = Lighting:FindFirstChild("VISION_GG_IntroBlur")
        if existingBlur then existingBlur:Destroy() end
    
        introBlur = Instance.new("BlurEffect")
        introBlur.Name = "VISION_GG_IntroBlur"
        introBlur.Size = 0
        introBlur.Parent = Lighting
        tn(introBlur, 0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {Size = 22}):Play()
    
        -- Glow overlay
        local glowOverlay = Instance.new("Frame", gui)
        glowOverlay.Size = UDim2.new(1, 0, 1, 0)
        glowOverlay.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        glowOverlay.BackgroundTransparency = 0.98
        glowOverlay.BorderSizePixel = 0
        glowOverlay.ZIndex = 3
        
        task.spawn(function()
            local breath = 0
            while gui and gui.Parent and introActive do
                task.wait()
                breath = breath + 0.02
                local pulse = 0.95 + math.sin(breath) * 0.03
                glowOverlay.BackgroundTransparency = pulse
            end
        end)
    
        -- Particles
        local particleContainer = Instance.new("Frame", gui)
        particleContainer.Size = UDim2.new(1, 0, 1, 0)
        particleContainer.BackgroundTransparency = 1
        particleContainer.ZIndex = 4
    
        local particles = {}
        for i = 1, 35 do
            local dot = Instance.new("Frame", particleContainer)
            local size = math.random(2, 5)
            dot.Size = UDim2.new(0, size, 0, size)
            dot.Position = UDim2.new(math.random(), 0, math.random(), 0)
            dot.BackgroundColor3 = Silver1
            dot.BackgroundTransparency = 0.3 + math.random() * 0.5
            dot.BorderSizePixel = 0
            dot.ZIndex = 4
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
            table.insert(particles, {
                frame = dot,
                speedX = (math.random() - 0.5) * 0.002,
                speedY = (math.random() - 0.5) * 0.002,
                floatSpeed = 0.5 + math.random() * 0.5,
                phase = math.random() * math.pi * 2,
            })
        end
    
        task.spawn(function()
            local t = 0
            while gui and gui.Parent and introActive do
                task.wait()
                t = t + 0.05
                for _, p in ipairs(particles) do
                    if p.frame and p.frame.Parent then
                        local newX = p.frame.Position.X.Scale + p.speedX + math.sin(t * p.floatSpeed + p.phase) * 0.001
                        local newY = p.frame.Position.Y.Scale + p.speedY + math.cos(t * p.floatSpeed + p.phase) * 0.001
                        if newX > 1 then newX = 0 end
                        if newX < 0 then newX = 1 end
                        if newY > 1 then newY = 0 end
                        if newY < 0 then newY = 1 end
                        p.frame.Position = UDim2.new(newX, 0, newY, 0)
                    end
                end
            end
        end)
    
        -- Loading ring
