        local progressText = Instance.new("TextLabel", gui)
        progressText.Size = UDim2.new(0, 60, 0, 20)
        progressText.AnchorPoint = Vector2.new(0.5, 0.5)
        progressText.Position = UDim2.new(0.5, 0, 0.86, 0)
