                glossStroke.Transparency = 0.08
                glossStroke.Color = Color3.fromRGB(255, 255, 255)
    
                local grad = Instance.new("UIGradient", lb)
                grad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(0.12, Color3.fromRGB(170, 170, 170)),
                    ColorSequenceKeypoint.new(0.28, Color3.fromRGB(35, 35, 35)),
                    ColorSequenceKeypoint.new(0.48, Color3.fromRGB(5, 5, 5)),
                    ColorSequenceKeypoint.new(0.62, Color3.fromRGB(120, 120, 120)),
                    ColorSequenceKeypoint.new(0.76, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(0.88, Color3.fromRGB(45, 45, 45)),
                    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(5, 5, 5)),
                })
                grad.Rotation = 90
                grad.Offset = Vector2.new(0, -0.8)
    
                local ar = Instance.new("UIAspectRatioConstraint", lb)
                ar.AspectRatio = 0.6
    
                le[i] = lb
            end
            return co, le
        end
    
        local fc, fl = bw("VISION.GG", 0.34, Silver1, 55, 0)
        local dc, dl = bw("DUEL", 0.46, Silver2, 55, 0)
    
        task.spawn(function()
