                    ringArc.Rotation = -90 + angle
                    progressText.Text = math.floor(progress * 100) .. "%"
                    arcStroke.Transparency = 0.2 + (1 - progress) * 0.6
                    if progress >= 1 then break end
                    task.wait(0.04)
                end
                progressText.Text = "100%"
                arcStroke.Transparency = 0.2
