                spark.BackgroundColor3 = Silver1
                spark.BackgroundTransparency = 0.2
                spark.BorderSizePixel = 0
                spark.ZIndex = 10
                Instance.new("UICorner", spark).CornerRadius = UDim.new(1, 0)
                
                local targetX = 0.5 + (math.random() - 0.5) * 0.5
                local targetY = 0.78 + (math.random() - 0.5) * 0.5
                local dur = 0.2 + math.random() * 0.2
                
                tn(spark, dur, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {
                    Position = UDim2.new(targetX, 0, targetY, 0),
                    BackgroundTransparency = 1,
                    Size = UDim2.new(0, 0, 0, 0)
                }):Play()
                task.delay(dur, function() pcall(function() spark:Destroy() end) end)
            end
        end)
    
        task.delay(9.8, function()
            if not introActive then return end
            introCompleted = true
    
            if introSound then
                introSound:Stop()
                introSound:Destroy()
                introSound = nil
            end
    
            local ot = 0.4
            for _, lt in ipairs(fl) do tn(lt, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {TextTransparency = 1}):Play() end
            for _, lt in ipairs(dl) do tn(lt, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {TextTransparency = 1}):Play() end
            tn(loadingRing, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {BackgroundTransparency = 1}):Play()
            tn(progressText, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {TextTransparency = 1}):Play()
            tn(overlay, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {BackgroundTransparency = 1}):Play()
            tn(glowOverlay, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {BackgroundTransparency = 1}):Play()
            tn(skipBtn, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {BackgroundTransparency = 1, TextTransparency = 1}):Play()
            tn(skipStroke, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {Transparency = 1}):Play()
            tn(skipArrow, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {TextTransparency = 1}):Play()
            if introBlur and introBlur.Parent then
                tn(introBlur, ot + 0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {Size = 0}):Play()
            end
            for _, p in ipairs(particles) do
                if p.frame then
                    tn(p.frame, ot, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {BackgroundTransparency = 1}):Play()
                end
            end
            task.delay(ot + 0.2, function()
                if not introCompleted then return end
                uf()
                pcall(function()
                    if introBlur and introBlur.Parent then introBlur:Destroy() end
                end)
                if gui and gui.Parent then gui:Destroy() end
                if onComplete then onComplete() end
            end)
        end)
    end
    
    -- ============================================================
    -- MAIN GUI FUNCTION (with background image sa menu)
    -- ============================================================
    local function startMainGUI()
        math.randomseed(math.floor(tick() * 1e7) % (2^31))
        local _INSTANCE_TOKEN = string.format("%08x-%08x-%08x", math.floor(tick() * 1e4) % 0x100000000, math.floor(os.clock() * 1e6) % 0x100000000, math.random(0, 0x7FFFFFFF) )
        local _instDead = false
        if _G._AKAI_DUELS_KILL and typeof(_G._AKAI_DUELS_KILL) == "Instance" then
            pcall(function() _G._AKAI_DUELS_KILL:Fire() end)
            task.defer(function() pcall(function() _G._AKAI_DUELS_KILL:Destroy() end) end)
        end
        _G._AKAI_DUELS_TOKEN = _INSTANCE_TOKEN
        local function isAlive()
            return not _instDead and _G._AKAI_DUELS_TOKEN == _INSTANCE_TOKEN
        end
        local _rawConns = {}
        local function rawConn(signal, fn)
            local conn
            conn = signal:Connect(function(...)
                if not isAlive() then
                    pcall(function() conn:Disconnect() end)
                    return
                end
                fn(...)
            end)
            table.insert(_rawConns, conn)
            return conn
        end
        local function _killRawConns()
            for _, c in ipairs(_rawConns) do
                pcall(function() c:Disconnect() end)
            end
            table.clear(_rawConns)
        end
        local _killBE = Instance.new("BindableEvent")
        _G._AKAI_DUELS_KILL = _killBE
        _killBE.Event:Connect(function()
            _instDead = true
            _killRawConns()
            stopAllNeonBorders()
        end)
    
        repeat task.wait() until game:IsLoaded()
    
