                VISION_GG_HUD=true,
                VISION_GG_Hub=true,
                VISION_GG_HubV2=true,
                amiriUI=true,
                AutoStealBar=true,
                amiri=true,
            }
            for _, container in ipairs({PGui, game:GetService("CoreGui")}) do
                for _, child in ipairs(container:GetChildren()) do
                    local n = child.Name
                    if EXACT[n] or n:sub(1, 4):lower() == "amiri" then
                        pcall(function() child:Destroy() end)
                    end
                end
            end
        end
