        -- ============================================================
        -- ANIMATED NEON BORDER SYSTEM
        -- ============================================================
        local _neonConns = {}
    
        local function addNeonStroke(parent, thickness, baseColor, activeColor, speed, pulseSpeed)
            -- Gray outline + bright white highlight that slowly travels around the edge.
            thickness = thickness or 1.5
            speed = speed or 18 -- slightly faster white highlight
    
            local stroke = Instance.new("UIStroke")
            stroke.Name = "GrayWhiteRotatingBorder"
            stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            stroke.LineJoinMode = Enum.LineJoinMode.Round
            stroke.Thickness = thickness
            stroke.Transparency = 0
            stroke.Color = CURRENT_GUI_COLOR
            stroke.Parent = parent
            registerThemeObject(stroke, "stroke")
    
            local grad = Instance.new("UIGradient")
            grad.Name = "WhiteRotatingHighlight"
            grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(95,95,95)),
                ColorSequenceKeypoint.new(0.32, Color3.fromRGB(150,150,150)),
                ColorSequenceKeypoint.new(0.46, Color3.fromRGB(255,255,255)),
                ColorSequenceKeypoint.new(0.54, Color3.fromRGB(255,255,255)),
                ColorSequenceKeypoint.new(0.68, Color3.fromRGB(150,150,150)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(95,95,95)),
            })
            grad.Rotation = 0
            grad.Parent = stroke
    
            local t = 0
            local conn = RunService.Heartbeat:Connect(function(dt)
                if not parent or not parent.Parent or not stroke.Parent then
                    if conn and conn.Connected then conn:Disconnect() end
                    return
                end
                t = t + dt
                grad.Rotation = (t * speed) % 360
            end)
            table.insert(_neonConns, conn)
    
            local function setActive(on)
                -- Keep the same gray outline/white moving highlight whether active or not.
                if stroke and stroke.Parent then
                    stroke.Thickness = on and (thickness + 0.3) or thickness
                    stroke.Transparency = 0
                end
            end
    
            local function destroy()
                if conn and conn.Connected then conn:Disconnect() end
                pcall(function() stroke:Destroy() end)
                for i, c in ipairs(_neonConns) do
                    if c == conn then table.remove(_neonConns, i); break end
                end
            end
    
            return stroke, setActive, destroy
        end
    
        local function buildNeonBorder(parent, thickness, speed, pulseSpeed)
            thickness = thickness or 2
            speed = speed or 55
            pulseSpeed = pulseSpeed or 0.8
    
            local stroke = Instance.new("UIStroke", parent)
            stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            stroke.LineJoinMode = Enum.LineJoinMode.Round
            stroke.Thickness = thickness
            stroke.Transparency = 0
            stroke.Color = CURRENT_GUI_COLOR
            registerThemeObject(stroke, "stroke")
    
            local grad = Instance.new("UIGradient", stroke)
            grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(60, 65, 70)),
                ColorSequenceKeypoint.new(0.40, Color3.fromRGB(60, 65, 70)),
                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(0.60, Color3.fromRGB(60, 65, 70)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(60, 65, 70)),
            })
    
            local t = 0
            local conn = RunService.Heartbeat:Connect(function(dt)
                if not parent or not parent.Parent then return end
                t = t + dt
                grad.Rotation = (t * speed) % 360
                local p = (math.sin(t * pulseSpeed * math.pi * 2) + 1) / 2
                stroke.Transparency = 0.25 * (1 - p)
            end)
    
            table.insert(_neonConns, conn)
            return stroke
        end
    
        local function stopAllNeonBorders()
            for _, conn in ipairs(_neonConns) do
                if conn and conn.Connected then
                    pcall(function() conn:Disconnect() end)
                end
            end
            _neonConns = {}
        end
    
        local function fadeLine(parent, yPos)
            local line = Instance.new("Frame")
            line.Size = UDim2.new(1, -28, 0, 1)
            line.Position = UDim2.new(0, 14, 0, yPos)
            line.BackgroundColor3 = Color3.fromRGB(255,255,255)
            line.BorderSizePixel = 0
            line.ZIndex = 4
            line.Parent = parent
            local g = Instance.new("UIGradient")
            g.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(0.15, 0.2),
                NumberSequenceKeypoint.new(0.5, 0),
                NumberSequenceKeypoint.new(0.85, 0.2),
                NumberSequenceKeypoint.new(1, 1),
            })
            g.Parent = line
            return line
        end
    
