            -- GUI POP/ZOOM OPEN-CLOSE ANIMATION (UIScale + Fade)
            -- The whole menu smoothly pops in/out instead of instantly appearing/disappearing.
            local menuScale = Instance.new("UIScale")
            menuScale.Name = "MenuPopScale"
            menuScale.Scale = 1
            menuScale.Parent = Container
    
            local menuAnimationBusy = false
            local MENU_OPEN_TIME = 0.22
            local MENU_CLOSE_TIME = 0.16
            local menuFadeTargets = {}
    
            local function captureMenuFadeTargets()
                menuFadeTargets = {}
                for _, obj in ipairs(Container:GetDescendants()) do
                    local data = {}
                    local isTitle = (_AMIRI._TitleContainer and obj:IsDescendantOf(_AMIRI._TitleContainer))
                    if isTitle then
                        continue
                    end
                    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                        data.TextTransparency = obj.TextTransparency
                        data.TextStrokeTransparency = obj.TextStrokeTransparency
                    end
                    if (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) and obj ~= _AMIRI._BgImage then
                        data.ImageTransparency = obj.ImageTransparency
                    end
                    if obj:IsA("GuiObject") and obj.BackgroundTransparency < 1 then
                        data.BackgroundTransparency = obj.BackgroundTransparency
                    end
                    if obj:IsA("UIStroke") then
                        data.StrokeTransparency = obj.Transparency
                    end
                    if next(data) then
                        menuFadeTargets[obj] = data
                    end
                end
            end
    
            local function tweenMenuTransparency(hidden, duration)
                local TS = game:GetService("TweenService")
                for obj, data in pairs(menuFadeTargets) do
                    if obj and obj.Parent then
                        local props = {}
                        if data.TextTransparency ~= nil then
                            props.TextTransparency = hidden and 1 or data.TextTransparency
                            props.TextStrokeTransparency = hidden and 1 or data.TextStrokeTransparency
                        end
                        if data.ImageTransparency ~= nil then
                            props.ImageTransparency = hidden and 1 or data.ImageTransparency
                        end
                        if data.BackgroundTransparency ~= nil then
                            props.BackgroundTransparency = hidden and 1 or data.BackgroundTransparency
                        end
                        if data.StrokeTransparency ~= nil then
                            props.Transparency = hidden and 1 or data.StrokeTransparency
                        end
                        if next(props) then
                            TS:Create(obj, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
                        end
                    end
                end
            end
    
            local function openMenuAnimated()
                if menuAnimationBusy then return end
                menuAnimationBusy = true
                local TS = game:GetService("TweenService")
                Container.Visible = true
                menuScale.Scale = 0.88
                -- Keep the selected background image permanently visible.
                if _AMIRI._BgImage and _AMIRI._BgImage.Parent then
                    _AMIRI._BgImage.Visible = true
                    _AMIRI._BgImage.ImageTransparency = 0
                end
                tweenMenuTransparency(1, 0)
    
                local scaleTween = TS:Create(menuScale, TweenInfo.new(MENU_OPEN_TIME, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1})
                scaleTween:Play()
                tweenMenuTransparency(0, MENU_OPEN_TIME)
                scaleTween.Completed:Wait()
                menuAnimationBusy = false
            end
    
            local function closeMenuAnimated()
                if menuAnimationBusy then return end
                menuAnimationBusy = true
                local TS = game:GetService("TweenService")
                local scaleTween = TS:Create(menuScale, TweenInfo.new(MENU_CLOSE_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.88})
                scaleTween:Play()
                tweenMenuTransparency(1, MENU_CLOSE_TIME)
                scaleTween.Completed:Wait()
                Container.Visible = false
                menuScale.Scale = 1
                -- Never leave the background image transparent after closing.
                if _AMIRI._BgImage and _AMIRI._BgImage.Parent then
                    _AMIRI._BgImage.Visible = true
                    _AMIRI._BgImage.ImageTransparency = 0
                end
                menuAnimationBusy = false
            end
    
