            applyFontToGui = function()
                local entry = _FONTS[_currentFontIdx]
                if not entry then return end
                pcall(function()
                    local ok, face = pcall(Font.new, entry.path)
                    if not ok or not face then return end
                    local _noFontOverride = { TitleMain = true, DiscordLink = true, ShowBtn = true }
                    local function applyToGui(gui)
                        for _, desc in ipairs(gui:GetDescendants()) do
                            pcall(function()
                                -- Keep the floating "VISION.GG" ShowBtn logo font fixed.
                                -- Changing Font Style must NEVER change this button.
                                local isProtectedButton = (ShowBtn and (desc == ShowBtn or desc:IsDescendantOf(ShowBtn)))
                                local isTitle = (_AMIRI._TitleContainer and desc:IsDescendantOf(_AMIRI._TitleContainer))
                                if (desc:IsA("TextLabel") or desc:IsA("TextButton") or desc:IsA("TextBox"))
                                    and not _noFontOverride[desc.Name]
                                    and not isProtectedButton
                                    and not isTitle then
                                    desc.FontFace = face
                                end
                            end)
                        end
                    end
                    applyToGui(ScreenGui)
                    if _AMIRI._extraGuis then
                        for _, gui in ipairs(_AMIRI._extraGuis) do
