            _AMIRI._TitleContainer = Wordmark
    
            local wordmarkLetters = {
                {"V", 0.055, 0.50, 39, -2},
                {"I", 0.165, 0.50, 39, 1},
                {"S", 0.275, 0.48, 39, -1},
                {"I", 0.385, 0.50, 39, 1},
                {"O", 0.495, 0.48, 39, -1},
                {"N", 0.605, 0.50, 39, 2},
                {".", 0.715, 0.55, 30, -1},
                {"G", 0.805, 0.48, 39, 1},
                {"G", 0.915, 0.50, 39, -1},
            }
    
            local function addChromeGradient(label)
                local g = Instance.new("UIGradient", label)
                g.Name = "ChromeGradient"
                g.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0.00, Color3.fromRGB(70,70,70)),
                    ColorSequenceKeypoint.new(0.16, Color3.fromRGB(235,235,235)),
                    ColorSequenceKeypoint.new(0.32, Color3.fromRGB(105,105,105)),
                    ColorSequenceKeypoint.new(0.50, Color3.fromRGB(255,255,255)),
                    ColorSequenceKeypoint.new(0.68, Color3.fromRGB(115,115,115)),
                    ColorSequenceKeypoint.new(0.84, Color3.fromRGB(245,245,245)),
                    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(55,55,55)),
                })
                g.Rotation = 90
                return g
            end
    
            local function makeWordmarkLetter(char, x, y, size, rot, index)
                local holder = Instance.new("Frame", Wordmark)
                holder.Name = "WordmarkLetter" .. index
                holder.AnchorPoint = Vector2.new(0.5, 0.5)
                holder.Position = UDim2.new(x, 0, y, 0)
                holder.Size = UDim2.new(0, 58, 0, 66)
                holder.BackgroundTransparency = 1
                holder.BorderSizePixel = 0
                holder.Rotation = rot
                holder.ZIndex = 21
    
                -- Deep offset gives the thick black depth seen on the reference.
                local shadow = Instance.new("TextLabel", holder)
                shadow.Name = "Depth"
                shadow.Size = UDim2.new(1, 0, 1, 0)
                shadow.Position = UDim2.new(0, 3, 0, 5)
                shadow.BackgroundTransparency = 1
                shadow.Text = char
                shadow.TextColor3 = Color3.fromRGB(8,8,8)
                shadow.TextSize = size + 5
                shadow.Font = Enum.Font.GothamBlack
                shadow.TextStrokeColor3 = Color3.fromRGB(0,0,0)
                shadow.TextStrokeTransparency = 0
                shadow.TextXAlignment = Enum.TextXAlignment.Center
                shadow.TextYAlignment = Enum.TextYAlignment.Center
                shadow.ZIndex = 21
    
                -- Soft metallic edge behind the face.
                local edge = Instance.new("TextLabel", holder)
                edge.Name = "MetalEdge"
                edge.Size = UDim2.new(1, 0, 1, 0)
                edge.Position = UDim2.new(0, 0, 0, 1)
                edge.BackgroundTransparency = 1
                edge.Text = char
                edge.TextColor3 = Color3.fromRGB(95,95,95)
                edge.TextSize = size + 2
                edge.Font = Enum.Font.GothamBlack
                edge.TextStrokeColor3 = Color3.fromRGB(235,235,235)
                edge.TextStrokeTransparency = 0.15
                edge.TextXAlignment = Enum.TextXAlignment.Center
                edge.TextYAlignment = Enum.TextYAlignment.Center
                edge.ZIndex = 22
    
                -- Main chrome face.
                local front = Instance.new("TextLabel", holder)
                front.Name = "ChromeFront"
                front.Size = UDim2.new(1, 0, 1, 0)
                front.BackgroundTransparency = 1
                front.Text = char
                front.TextColor3 = Color3.fromRGB(220,220,220)
                front.TextSize = size
                front.Font = Enum.Font.GothamBlack
                front.TextStrokeColor3 = Color3.fromRGB(245,245,245)
                front.TextStrokeTransparency = 0.18
                front.TextXAlignment = Enum.TextXAlignment.Center
                front.TextYAlignment = Enum.TextYAlignment.Center
                front.ZIndex = 23
                addChromeGradient(front)
    
                -- Narrow white highlight offsets the face and makes it look glossy.
                local highlight = Instance.new("TextLabel", holder)
                highlight.Name = "Highlight"
                highlight.Size = UDim2.new(1, 0, 1, 0)
                highlight.Position = UDim2.new(0, 0, 0, -1)
                highlight.BackgroundTransparency = 1
                highlight.Text = char
                highlight.TextColor3 = Color3.fromRGB(255,255,255)
                highlight.TextSize = size - 2
                highlight.Font = Enum.Font.GothamBlack
                highlight.TextTransparency = 0.82
                highlight.TextStrokeColor3 = Color3.fromRGB(255,255,255)
                highlight.TextStrokeTransparency = 0.55
                highlight.TextXAlignment = Enum.TextXAlignment.Center
                highlight.TextYAlignment = Enum.TextYAlignment.Center
                highlight.ZIndex = 24
            end
    
            for i, item in ipairs(wordmarkLetters) do
                makeWordmarkLetter(item[1], item[2], item[3], item[4], item[5], i)
            end
    
            local wordmarkLine = Instance.new("Frame", Wordmark)
            wordmarkLine.Name = "WordmarkUnderline"
            wordmarkLine.AnchorPoint = Vector2.new(0.5, 0)
            wordmarkLine.Position = UDim2.new(0.5, 0, 0.92, 0)
            wordmarkLine.Size = UDim2.new(0.66, 0, 0, 3)
            wordmarkLine.BackgroundColor3 = Color3.fromRGB(225,225,225)
            wordmarkLine.BackgroundTransparency = 0.10
            wordmarkLine.BorderSizePixel = 0
            wordmarkLine.Rotation = -2
            wordmarkLine.ZIndex = 21
            addCorner(wordmarkLine, 2)
            local lineGrad = Instance.new("UIGradient", wordmarkLine)
            lineGrad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(55,55,55)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255,255,255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(55,55,55)),
            })
    
            -- Keep title layers out of any external font override.
            -- Walang avatar/profile circle sa tabi ng AMIRI HUB.
    
            local DividerLine = Instance.new("Frame", HeaderFrame)
            DividerLine.Size = UDim2.new(1,-24,0,1)
            DividerLine.Position = UDim2.new(0,12,0,104)
            DividerLine.BackgroundColor3 = Color3.fromRGB(200,200,200)
            DividerLine.BackgroundTransparency = 0.6
            DividerLine.BorderSizePixel = 0
            DividerLine.ZIndex = 7
    
            local MinimizeBtn = Instance.new("TextButton", HeaderFrame)
            MinimizeBtn.Size = UDim2.new(0,26,0,26)
            MinimizeBtn.Position = UDim2.new(1,-38,0,10)
            MinimizeBtn.BackgroundColor3 = Color3.fromRGB(40,40,40)
            MinimizeBtn.BackgroundTransparency = 0
            MinimizeBtn.BorderSizePixel = 0
            MinimizeBtn.Text = "-"
            MinimizeBtn.TextColor3 = Color3.fromRGB(255,255,255)
            MinimizeBtn.TextSize = 18
            MinimizeBtn.Font = Enum.Font.GothamBlack
            MinimizeBtn.ZIndex = 9
            MinimizeBtn.Active = true
            addCorner(MinimizeBtn, 6)
            local minStroke, _ = addNeonStroke(MinimizeBtn, 1, Color3.fromRGB(120,120,120), Color3.fromRGB(200,200,200))
            MinimizeBtn.MouseEnter:Connect(function()
                tween(MinimizeBtn, { BackgroundTransparency = 0.2, TextColor3 = Color3.fromRGB(200,200,200) })
            end)
            MinimizeBtn.MouseLeave:Connect(function()
                tween(MinimizeBtn, { BackgroundTransparency = 0, TextColor3 = Color3.fromRGB(255,255,255) })
            end)
            MinimizeBtn.MouseButton1Click:Connect(function()
                task.spawn(closeMenuAnimated)
            end)
    
            -- ShowBtn toggles menu visibility with the GUI Pop/Zoom + Fade animation.
            ShowBtn.MouseButton1Click:Connect(function()
                if _showBtnDragged then _showBtnDragged = false; return end
                if Container.Visible then
                    task.spawn(closeMenuAnimated)
                else
                    task.spawn(openMenuAnimated)
                end
            end)
    
            local TabBar = Instance.new("Frame")
            TabBar.Size = UDim2.new(1,-20,0,44)
            TabBar.Position = UDim2.new(0,10,0,112)
            TabBar.BackgroundTransparency = 1
            TabBar.ZIndex = 10
            TabBar.Parent = Panel
            TabBar.Visible = true
    
            TabScroll = Instance.new("ScrollingFrame")
            TabScroll.Size = UDim2.new(1,0,1,0)
            TabScroll.Position = UDim2.new(0,0,0,0)
            TabScroll.BackgroundTransparency = 1
            TabScroll.BorderSizePixel = 0
            TabScroll.ScrollBarThickness = 0
            TabScroll.ScrollingDirection = Enum.ScrollingDirection.X
            TabScroll.CanvasSize = UDim2.new(0,0,0,0)
            TabScroll.AutomaticCanvasSize = Enum.AutomaticSize.X
            TabScroll.ElasticBehavior = Enum.ElasticBehavior.Never
            TabScroll.ZIndex = 6
            TabScroll.Parent = TabBar
    
            local TabLayout = Instance.new("UIListLayout")
            TabLayout.FillDirection = Enum.FillDirection.Horizontal
            TabLayout.SortOrder = Enum.SortOrder.LayoutOrder
            -- Walang gap sa pagitan ng tabs
            TabLayout.Padding = UDim.new(0, 4)
            TabLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
            TabLayout.Parent = TabScroll
    
            Content = Instance.new("ScrollingFrame")
            Content.Name = "Content"
            Content.Size = UDim2.new(1,0,1,-154)
            Content.Position = UDim2.new(0,0,0,154)
            Content.BackgroundTransparency = 1
            Content.BorderSizePixel = 0
            Content.ScrollBarThickness = 2
            Content.ScrollBarImageColor3 = Color3.fromRGB(100,100,100)
            Content.CanvasSize = UDim2.new(0,0,0,0)
            Content.AutomaticCanvasSize = Enum.AutomaticSize.Y
            Content.ZIndex = 10
            Content.Parent = Panel
    
            local ContentList = Instance.new("UIListLayout")
            ContentList.SortOrder = Enum.SortOrder.LayoutOrder
            ContentList.Padding = UDim.new(0, 4)
            ContentList.Parent = Content
    
            local ContentPad = Instance.new("UIPadding")
            ContentPad.PaddingLeft = UDim.new(0,12)
            ContentPad.PaddingRight = UDim.new(0,12)
            ContentPad.PaddingTop = UDim.new(0, 8)
            ContentPad.PaddingBottom = UDim.new(0, 8)
            ContentPad.Parent = Content
    
            -- ============================================================
            -- DRAG FUNCTIONALITY (FIXED)
            -- ============================================================
            do
                local dragData = {
                    dragging = false,
                    startMouse = Vector2.new(),
                    startAbsPos = Vector2.new(),
                }
                HeaderFrame.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        local mousePos = input.Position
                        local minBtnPos = MinimizeBtn.AbsolutePosition
                        local minBtnSize = MinimizeBtn.AbsoluteSize
                        if minBtnPos and minBtnSize and 
                           mousePos.X >= minBtnPos.X and mousePos.X <= minBtnPos.X + minBtnSize.X and
                           mousePos.Y >= minBtnPos.Y and mousePos.Y <= minBtnPos.Y + minBtnSize.Y then
                            return
                        end
                        dragData.dragging = true
                        dragData.startMouse = input.Position
                        dragData.startAbsPos = Container.AbsolutePosition
                    end
                end)
                HeaderFrame.InputChanged:Connect(function(input)
                    if not dragData.dragging then return end
                    if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local delta = input.Position - dragData.startMouse
                    local newX = dragData.startAbsPos.X + delta.X
                    local newY = dragData.startAbsPos.Y + delta.Y
                    local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
                    local menuSize = Container.AbsoluteSize
                    if menuSize.X > 0 and menuSize.Y > 0 then
                        newX = math.clamp(newX, 0, viewport.X - menuSize.X)
                        newY = math.clamp(newY, 0, viewport.Y - menuSize.Y)
                    end
                    Container.Position = UDim2.new(0, newX, 0, newY)
                end)
                HeaderFrame.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragData.dragging = false
                        local pos = Container.Position
                        _configState["menuXScale"] = pos.X.Scale
                        _configState["menuXOffset"] = pos.X.Offset
                        _configState["menuYScale"] = pos.Y.Scale
                        _configState["menuYOffset"] = pos.Y.Offset
                        _autoSaveConfig()
                    end
                end)
            end
            -- Capture the normal visual state, then start the first pop/zoom animation.
            captureMenuFadeTargets()
            task.defer(function()
                if Container and Container.Parent then
                    openMenuAnimated()
                end
            end)
        end
    
        -- ============================================================
        -- UI HELPERS (UPDATED toggleRow with blush light black effect)
        -- ============================================================
        local ROW_ALPHA = 0.96
        local function hoverRow(row, baseAlpha)
            local hit = Instance.new("TextButton")
            hit.Size = UDim2.new(1,0,1,0)
            hit.BackgroundTransparency = 1
            hit.Text = ""
            hit.ZIndex = 0
            hit.Parent = row
            hit.MouseEnter:Connect(function()
                tween(row, { BackgroundTransparency = baseAlpha - 0.06 })
            end)
            hit.MouseLeave:Connect(function()
                tween(row, { BackgroundTransparency = baseAlpha })
            end)
            return hit
        end
    
