            if onAction then
                hit.MouseButton1Click:Connect(onAction)
            end
            return Row
        end
    
        local _toggleRegistry = {}
        local CONFIG_FILE = "Amiri.json"
    
        local function loadConfig()
            local existsOk, exists = false, false
            if type(isfile) == "function" then
                existsOk, exists = pcall(isfile, CONFIG_FILE)
            end
            if not existsOk or not exists then return {} end
            local ok, raw = false, nil
            if type(readfile) == "function" then
                ok, raw = pcall(readfile, CONFIG_FILE)
            end
            if not ok or not raw or raw == "" then return {} end
            local ok2, data = pcall(function() return HS:JSONDecode(raw) end)
            return (ok2 and type(data) == "table") and data or {}
        end
    
        local function saveConfigNow(state)
            local ok, encoded = pcall(function() return HS:JSONEncode(state) end)
            if not ok or not encoded then return end
            if type(writefile) == "function" then pcall(writefile, CONFIG_FILE, encoded) end
        end
    
        local _configState = loadConfig()
        local _configSaveTimer = nil
        local function _autoSaveConfig()
            if _configSaveTimer then task.cancel(_configSaveTimer) end
            _configSaveTimer = task.delay(0.5, function()
                saveConfigNow(_configState)
            end)
        end
    
        local function _regToggle(parent, label, startOn, order, key, onToggle)
            local row, setState = toggleRow(parent, label, startOn, order, function(on)
                _configState[key] = on
                if onToggle then onToggle(on) end
                _autoSaveConfig()
            end)
            table.insert(_toggleRegistry, {setState = setState, key = key, callback = onToggle})
            return row, setState
        end
    
        local function _regToggleOnly(key, startOn, onToggle)
            local setState
            setState = function(on)
                _configState[key] = on
                if onToggle then onToggle(on) end
                _autoSaveConfig()
            end
            table.insert(_toggleRegistry, {setState = setState, key = key, callback = onToggle})
            setState(startOn)
        end
    
        local function _regAction(key, label, actionFn)
            _AMIRI._actionRegistry[key] = {label = label, fn = actionFn}
        end
    
        _AMIRI._syncToggleOff = function(key)
            _configState[key] = false
            for _, e in ipairs(_toggleRegistry) do
                if e.key == key then e.setState(false); break end
            end
            if key == "AUTOLEFT" and _AMIRI._setALOn then _AMIRI._setALOn(false) end
            if key == "AUTORIGHT" and _AMIRI._setAROn then _AMIRI._setAROn(false) end
            if key == "AUTOBAT" and _AMIRI._setABOn then _AMIRI._setABOn(false) end
            if key == "TPBAT" and _AMIRI._setTPBOn then _AMIRI._setTPBOn(false) end
            if key == "CARRYSPEED" and _AMIRI._setCarryFB then _AMIRI._setCarryFB(false) end
            if key == "LAGGERSPEED" and _AMIRI._setLaggerFB then _AMIRI._setLaggerFB(false) end
            if key == "LAGGER_CARRY" and _AMIRI._setLagFB then _AMIRI._setLagFB(false) end
            _autoSaveConfig()
        end
    
        local TAB_NAMES = { "SPEED", "COMBAT", "VISUAL", "KEYBIND", "SETTING" }
