        do
            for i, name in ipairs(TAB_NAMES) do
                local isActive = (name == activeTab)
                local wrap = Instance.new("Frame")
                -- Rounded box container for each tab; tabs stay tightly packed.
                wrap.Size = UDim2.new(0, 68, 0, 42)
                wrap.BackgroundColor3 = Color3.fromRGB(22,22,22)
                wrap.BackgroundTransparency = isActive and 0.08 or 0.22
                wrap.BorderSizePixel = 0
                wrap.LayoutOrder = i
                wrap.Parent = TabScroll
                addCorner(wrap, 12)
    
                local wrapStroke = Instance.new("UIStroke")
                wrapStroke.Thickness = 1
                wrapStroke.Color = isActive and Color3.fromRGB(255,255,255) or Color3.fromRGB(55,55,55)
                wrapStroke.Transparency = isActive and 0 or 0.25
                wrapStroke.Parent = wrap
    
                local navBtn = Instance.new("TextButton", wrap)
                navBtn.Size = UDim2.new(1, 0, 1, 0)
                navBtn.BackgroundTransparency = 1
                navBtn.TextColor3 = isActive and Color3.fromRGB(255,255,255) or Color3.fromRGB(255,255,255)
                navBtn.TextSize = 9
                navBtn.Font = Enum.Font.GothamBold
                navBtn.ZIndex = 7
                navBtn.Text = string.upper(name)
                local pip = Instance.new("Frame", wrap)
                pip.Size = UDim2.new(0.55, 0, 0, 2)
                pip.Position = UDim2.new(0.225, 0, 1, -3)
                pip.BackgroundColor3 = Color3.fromRGB(255,255,255)
                pip.BackgroundTransparency = isActive and 0 or 1
                pip.BorderSizePixel = 0
                addCorner(pip, 1)
                tabButtons[name] = navBtn
                tabPips[name] = pip
                navBtn.MouseEnter:Connect(function()
                    if activeTab ~= name then
                        tween(navBtn, { TextColor3 = Color3.fromRGB(200,200,200) })
                    end
                end)
                navBtn.MouseLeave:Connect(function()
                    if activeTab ~= name then
                        tween(navBtn, { TextColor3 = Color3.fromRGB(130,130,130) })
                    end
                end)
                navBtn.MouseButton1Click:Connect(function()
                    if activeTab == name then return end
                    tween(tabButtons[activeTab], { TextColor3 = Color3.fromRGB(180,180,180) })
                    tween(tabPips[activeTab], { BackgroundTransparency = 1 })
                    local oldWrap = tabButtons[activeTab].Parent
                    tween(oldWrap, { BackgroundTransparency = 0.22 })
                    local oldStroke = oldWrap:FindFirstChildOfClass("UIStroke")
                    if oldStroke then tween(oldStroke, { Color = Color3.fromRGB(55,55,55), Transparency = 0.25 }) end
                    tabPages[activeTab].Visible = false
                    activeTab = name
                    tabPages[activeTab].Visible = true
                    tween(tabButtons[activeTab], { TextColor3 = Color3.fromRGB(255,255,255) })
                    tween(tabPips[activeTab], { BackgroundTransparency = 0 })
                    local newWrap = tabButtons[activeTab].Parent
                    tween(newWrap, { BackgroundTransparency = 0.08 })
                    local newStroke = newWrap:FindFirstChildOfClass("UIStroke")
                    if newStroke then tween(newStroke, { Color = Color3.fromRGB(255,255,255), Transparency = 0 }) end
                end)
            end
        end
    
