                    for _, entry in ipairs(_toggleRegistry) do
                        if entry.key == "VIZFPS" then
                            local newState = not _configState["VIZFPS"]
                            entry.setState(newState)
                            _configState["VIZFPS"] = newState
                            if entry.callback then pcall(entry.callback, newState) end
                            _autoSaveConfig()
                            break
                        end
                    end
                end
            end
        end)
    
