        local function isRagdollState(hum)
            if not hum then return true end
            local st = hum:GetState()
            return hum.PlatformStand or st==Enum.HumanoidStateType.Physics or st==Enum.HumanoidStateType.Ragdoll or st==Enum.HumanoidStateType.FallingDown
        end
    
        local function getActiveMoveSpeed()
            if laggerToggled then
                return laggerPhase==2 and LAGGER_CARRY_SPEED or LAGGER_SPEED
            end
            if speedMode then return CS end
            return NS
        end
    
        local function getAutoPathSpeed()
            if laggerToggled then return LAGGER_SPEED end
            return NS
        end
    
        local function getSpeedModeName()
            if laggerToggled then
                if laggerPhase == 2 then return "Lagger Carry"
                else return "Lagger Normal" end
            else
                if speedMode then return "Speed Carry"
                else return "Speed Normal" end
            end
        end
    
        -- ============================================================
        -- SPEED LOGIC (REPLACED / STABLE)
        -- Uses Humanoid.WalkSpeed + horizontal AssemblyLinearVelocity.
        -- Keeps the existing NS / CS / LAGGER values and mode system.
        -- ============================================================
        rawConn(RunService.RenderStepped, function()
            local char = LP.Character
            if not char then return end
    
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
    
            if isRagdollState(hum) then
                lastMoveDir = Vector3.zero
                return
            end
    
            -- Other movement systems keep control while active.
            if autoBatEnabled or autoLeftEnabled or autoRightEnabled then
                return
            end
    
            local currentSpeed = math.max(0, tonumber(getActiveMoveSpeed()) or 16)
            hum.WalkSpeed = currentSpeed
    
            local moveDir = hum.MoveDirection
            if moveDir.Magnitude > 0.05 then
                local flat = Vector3.new(moveDir.X, 0, moveDir.Z)
                if flat.Magnitude > 0.001 then
                    flat = flat.Unit
                    lastMoveDir = flat
    
                    local currentY = hrp.AssemblyLinearVelocity.Y
                    hrp.AssemblyLinearVelocity = Vector3.new(
                        flat.X * currentSpeed,
                        currentY,
                        flat.Z * currentSpeed
                    )
                end
            else
                -- Stop only the horizontal speed; preserve jumping/falling velocity.
                local currentY = hrp.AssemblyLinearVelocity.Y
                hrp.AssemblyLinearVelocity = Vector3.new(0, currentY, 0)
            end
    
            -- Keep the existing speed display working.
            pcall(function()
                local head = char:FindFirstChild("Head")
                if not head then return end
                local bb = head:FindFirstChild("AmiriDuelsBB")
                if not bb then return end
                local sl = bb:FindFirstChild("SpeedBillLbl")
                if not sl then return end
    
                local modeName = getSpeedModeName()
                local v = hrp.AssemblyLinearVelocity
                local horizontalSpeed = Vector3.new(v.X, 0, v.Z).Magnitude
                sl.Text = string.format("%.1f | %s", horizontalSpeed, modeName)
            end)
        end)
    
        rawConn(RunService.Heartbeat, function()
            if not autoCarryEnabled then return end
            local c = LP.Character; if not c then return end
            local carrying = LP:GetAttribute("Stealing") == true
            if not carrying then
                for _,obj in ipairs(c:GetChildren()) do
                    if obj:IsA("Tool") and obj.Name:lower():find("brainrot") then carrying=true;break end
                end
            end
            if carrying == _autoCarryLast then return end
            _autoCarryLast = carrying
            if laggerToggled then
                laggerPhase = carrying and 2 or 0
            else
                speedMode = carrying
            end
        end)
    
        local function _cbCleanup()
            if _cbPart then
                pcall(function()
                    local c=LP.Character; local hrp=c and c:FindFirstChild("HumanoidRootPart")
                    if hrp and sethiddenproperty then sethiddenproperty(hrp,"PhysicsRepRootPart",hrp) end
                end)
                pcall(function() _cbPart:Destroy() end); _cbPart=nil
            end
        end
    
        rawConn(RunService.Heartbeat, function()
            if not _cbEnabled then
                if _cbPart then _cbCleanup() end; return
            end
            local c=LP.Character; if not c then return end
            local hrp=c:FindFirstChild("HumanoidRootPart"); if not hrp then return end
            local hum=c:FindFirstChildOfClass("Humanoid"); if not hum then return end
            if speedMode then
                if not _cbPart or _cbPart.Parent~=c then
                    pcall(function() if _cbPart then _cbPart:Destroy() end end)
                    local p=Instance.new("Part")
                    p.Name="AMIRICBPart"
                    p.Size=Vector3.new(1,1,1); p.Transparency=1
                    p.CanCollide=false; p.Massless=true; p.CFrame=hrp.CFrame; p.Parent=c
                    _cbPart=p
                    pcall(function()
                        if sethiddenproperty then sethiddenproperty(hrp,"PhysicsRepRootPart",_cbPart) end
                    end)
                end
                if (hrp.Position-_cbPart.Position).Magnitude > 50 then _cbPart.CFrame = hrp.CFrame end
                local md=hum.MoveDirection
                if md.Magnitude>0 then
                    _cbPart.AssemblyLinearVelocity=Vector3.new(md.X*CS_SERVER_SPEED,_cbPart.AssemblyLinearVelocity.Y,md.Z*CS_SERVER_SPEED)
                else
                    _cbPart.AssemblyLinearVelocity=Vector3.new(_cbPart.AssemblyLinearVelocity.X*0.5,_cbPart.AssemblyLinearVelocity.Y,_cbPart.AssemblyLinearVelocity.Z*0.5)
                end
            else
                if _cbPart then _cbCleanup() end
            end
        end)
    
        local function isMyPlotByName(pn)
            local ct = tick()
            if Steal.plotCache[pn]~=nil and (ct-(Steal.plotCacheTime[pn] or 0))<AG_CONFIG.PLOT_CACHE_DURATION then
                return Steal.plotCache[pn]
            end
            local plots = workspace:FindFirstChild("Plots"); if not plots then
                Steal.plotCache[pn]=false;Steal.plotCacheTime[pn]=ct;return false
            end
            local plot = plots:FindFirstChild(pn); if not plot then
                Steal.plotCache[pn]=false;Steal.plotCacheTime[pn]=ct;return false
            end
            local sign = plot:FindFirstChild("PlotSign")
            if sign then
                local yb=sign:FindFirstChild("YourBase");if yb and yb:IsA("BillboardGui") then
                    local r=yb.Enabled==true;Steal.plotCache[pn]=r;Steal.plotCacheTime[pn]=ct;return r
                end
            end
            Steal.plotCache[pn]=false;Steal.plotCacheTime[pn]=ct;return false
        end
    
        local function findNearestPrompt()
            local char=LP.Character;if not char then return nil end
            local root=char:FindFirstChild("HumanoidRootPart");if not root then return nil end
            local ct=tick()
            if ct-Steal.promptCacheTime<AG_CONFIG.PROMPT_CACHE_REFRESH and #Steal.cachedPrompts>0 then
                local np,nd=nil,math.huge
                for _,entry in ipairs(Steal.cachedPrompts) do
                    if entry.spawn and entry.prompt and entry.prompt.Parent then
                        local d=(entry.spawn.Position-root.Position).Magnitude
                        if d<=Steal.StealRadius and d<nd then np=entry.prompt;nd=d end
                    end
                end
                if np then return np end
            end
            Steal.cachedPrompts={};Steal.promptCacheTime=ct
            local plots=workspace:FindFirstChild("Plots");if not plots then return nil end
            local nearest,dist=nil,math.huge
            for _,plot in ipairs(plots:GetChildren()) do
                if isMyPlotByName(plot.Name) then continue end
                local pods=plot:FindFirstChild("AnimalPodiums");if not pods then continue end
                for _,pod in ipairs(pods:GetChildren()) do
                    local base=pod:FindFirstChild("Base");if not base then continue end
                    local sp=base:FindFirstChild("Spawn");if not sp then continue end
                    local d=(sp.Position-root.Position).Magnitude
                    if d<=Steal.StealRadius and d<dist then
                        local att=sp:FindFirstChild("PromptAttachment")
                        if att then
                            for _,p in ipairs(att:GetChildren()) do
                                if p:IsA("ProximityPrompt") and p.ActionText and p.ActionText:find("Steal") then
                                    nearest=p;dist=d;table.insert(Steal.cachedPrompts,{prompt=p,spawn=sp});break
                                end
                            end
                        end
                    end
                end
            end
            return nearest
        end
    
        local progressFill, progressPct
    
        local function resetProgressBar()
