        local function executeSteal(prompt)
            if isStealing then return end
            if not prompt or not prompt.Parent then return end
            local ct=tick(); if ct-Steal.lastStealTick<AG_CONFIG.STEAL_COOLDOWN then return end
            if not Steal.Data[prompt] then
                Steal.Data[prompt]={hold={},trigger={},ready=true}
                if type(getconnections) == "function" then
                    local okHold, holdConnections = pcall(getconnections, prompt.PromptButtonHoldBegan)
                    for _,c in ipairs((okHold and type(holdConnections) == "table") and holdConnections or {}) do
                        if c.Function then table.insert(Steal.Data[prompt].hold,c.Function) end
                    end
                    local okTrigger, triggerConnections = pcall(getconnections, prompt.Triggered)
                    for _,c in ipairs((okTrigger and type(triggerConnections) == "table") and triggerConnections or {}) do
                        if c.Function then table.insert(Steal.Data[prompt].trigger,c.Function) end
                    end
                end
            end
            local data=Steal.Data[prompt]; if not data.ready then return end
            data.ready=false; isStealing=true; Steal.lastStealTick=ct; stealStartTime=tick()
            task.spawn(function()
                for _,f in ipairs(data.hold) do pcall(f) end
                while tick()-stealStartTime<Steal.StealDuration do task.wait() end
                for _,f in ipairs(data.trigger) do pcall(f) end
                task.wait(0.05); data.ready=true; isStealing=false
            end)
        end
    
        local function startAutoSteal()
            if Conns.autoSteal then return end
            Conns.autoSteal = RunService.Heartbeat:Connect(function()
                if not isAlive() then Conns.autoSteal:Disconnect(); Conns.autoSteal=nil; return end
                if not Steal.AutoStealEnabled then return end
                if isStealing then
                    local ok,p = pcall(findNearestPrompt)
                    if not ok or not p then isStealing = false end
                    return
                end
                local ok,p = pcall(findNearestPrompt); if ok and p then pcall(executeSteal,p) end
            end)
        end
    
        local function stopAutoSteal()
            if Conns.autoSteal then Conns.autoSteal:Disconnect();Conns.autoSteal=nil end
