        local function getAutoBatTarget()
            local root=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"); if not root then return nil end
            local now=tick()
            if now-_autoBatLastScan<=0.1 and _autoBatTarget and _autoBatTarget.Parent then
                local hum=_autoBatTarget.Parent:FindFirstChildOfClass("Humanoid");if hum and hum.Health>0 then return _autoBatTarget end
            end
            _autoBatLastScan=now; _autoBatTarget=nil
            local closest,minDist=nil,math.huge
            for _,plr in ipairs(Players:GetPlayers()) do
                if plr~=LP and plr.Character then
                    local tRoot=plr.Character:FindFirstChild("HumanoidRootPart"); local hum=plr.Character:FindFirstChildOfClass("Humanoid")
                    if tRoot and hum and hum.Health>0 then
                        local dist=(tRoot.Position-root.Position).Magnitude;if dist<minDist then minDist=dist;closest=tRoot end
                    end
                end
            end
            _autoBatTarget=closest; return _autoBatTarget
        end
    
        local _autoBatHittingCooldown=false
        local function _autoBatSwing(char)
            if _autoBatHittingCooldown then return end
            _autoBatHittingCooldown = true
            task.spawn(function()
                local hum = char:FindFirstChildOfClass("Humanoid")
                local bat = char:FindFirstChildOfClass("Tool")
                if not bat then
                    local bp = LP:FindFirstChild("Backpack")
                    if bp then
                        for _, t in ipairs(bp:GetChildren()) do
                            local n = t.Name:lower()
                            if n:find("bat") or n:find("slap") then bat = t; break end
                        end
                    end
                end
                if bat then
                    if bat.Parent ~= char and hum then
                        pcall(function() hum:EquipTool(bat) end)
                        task.wait(0.05)
                    end
                    local remote = nil
                    for _, d in ipairs(bat:GetDescendants()) do
                        if d:IsA("RemoteEvent") then remote = d; break end
                    end
                    if remote then
                        pcall(function() remote:FireServer() end)
                        task.wait(0.12)
                        pcall(function() remote:FireServer() end)
                    else
                        pcall(function() bat:Activate() end)
                        task.wait(0.12)
                        pcall(function() bat:Activate() end)
                    end
                end
                task.delay(AUTO_BAT.SWING_COOLDOWN or 0.08, function() _autoBatHittingCooldown = false end)
            end)
        end
    
        local function _ab2TrySwing()
