        local function enableAutoBat()
            if autoLeftEnabled then autoLeftEnabled=false;stopAutoLeft();if _AMIRI._setALOn then _AMIRI._setALOn(false) end end
            if autoRightEnabled then autoRightEnabled=false;stopAutoRight();if _AMIRI._setAROn then _AMIRI._setAROn(false) end end
            autoBatEquippedThisRun=false; autoBatEnabled=true
            if _AMIRI._setABOn then _AMIRI._setABOn(true) end
        end
    
        local function disableAutoBat()
            autoBatEnabled=false; autoBatEquippedThisRun=false
            if _AMIRI._setABOn then _AMIRI._setABOn(false) end
            if _abBypassPart then _abBypassPart.AssemblyLinearVelocity=Vector3.zero end; _abCleanupProxy()
            local char=LP.Character; if char then
                local hum2=char:FindFirstChildOfClass("Humanoid");if hum2 then hum2.AutoRotate=true end
                local hrp=char:FindFirstChild("HumanoidRootPart");if hrp then hrp.AssemblyLinearVelocity=Vector3.zero;hrp.AssemblyAngularVelocity=Vector3.zero end
            end
            _autoBatTarget=nil
        end
    
        rawConn(RunService.RenderStepped, function()
            if not autoBatEnabled and not bypassAimbotToggled then return end
            local char = LP.Character; if not char then return end
            local root = char:FindFirstChild("HumanoidRootPart"); if not root then return end
            local hum = char:FindFirstChildOfClass("Humanoid"); if not hum then return end
            for _,p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Character then
                    for _,pt in ipairs(p.Character:GetDescendants()) do
                        if pt:IsA("BasePart") then pt.CanCollide = false end
                    end
                end
            end
            if not _abBypassPart or _abBypassPart.Parent ~= char then _abCreateProxy() end
            if autoBatEnabled and not autoBatEquippedThisRun then
                autoBatEquippedThisRun = true
                if not char:FindFirstChildOfClass("Tool") then
                    local bp = LP:FindFirstChildOfClass("Backpack")
                    if bp then
                        for _,t in ipairs(bp:GetChildren()) do
                            local n=t.Name:lower()
                            if n:find("bat") or n:find("slap") then
                                pcall(function() hum:EquipTool(t) end); break
                            end
                        end
                    end
                end
            end
            local target = getAutoBatTarget()
            if not target then hum.AutoRotate=true; root.AssemblyAngularVelocity=Vector3.zero; return end
            local myPos = root.Position
            local targetPos = target.Position
    
            if autoBatMode == "bypass" then
                hum.AutoRotate = false
                local F1_SPEED = AUTO_BAT.SPEED_BYPASS or 60
                local F1_VERT_SPEED = 65
                local F1_DIST = -1.8
                local F1_V_OFF = 1.2
                local F1_TURN_SPD = 360
                local F1_MAX_TURN = 36
                local targetVel = target.AssemblyLinearVelocity
                local velMag = targetVel.Magnitude
                local lead = velMag > 1 and (targetVel.Unit * 2) or Vector3.zero
                local aimPos = targetPos + lead + Vector3.new(0, F1_V_OFF, 0)
                local look = aimPos - root.Position
                local flatLook = Vector3.new(look.X, 0, look.Z)
                if look.Magnitude > 0.01 and flatLook.Magnitude > 0.01 then
                    local targetYaw = math.deg(math.atan2(-flatLook.X, -flatLook.Z))
                    local yawDelta = (targetYaw - root.Orientation.Y + 180) % 360 - 180
                    local absYaw = math.abs(yawDelta)
                    local boost = 1 + 5 * math.clamp((absYaw - 20) / 140, 0, 1)
                    local yawRate = math.clamp(math.rad(yawDelta) * F1_TURN_SPD * boost, -F1_MAX_TURN * boost, F1_MAX_TURN * boost)
                    local angLerp = math.min((35 + 65 * math.clamp((absYaw - 20) / 140, 0, 1)) * 0.016, 1)
                    pcall(function()
                        root.AssemblyAngularVelocity = root.AssemblyAngularVelocity:Lerp(Vector3.new(0, yawRate, 0), angLerp)
                    end)
                else
                    pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
                end
                local dir = look.Magnitude > 0.01 and look.Unit or Vector3.zero
                local standPos = aimPos - (dir * F1_DIST)
                local moveDir = standPos - root.Position
                local hDir = Vector3.new(moveDir.X, 0, moveDir.Z)
                local hVel = hDir.Magnitude > 0.1 and hDir.Unit * F1_SPEED or Vector3.zero
                local vVel = math.abs(moveDir.Y) > 0.1 and Vector3.new(0, math.sign(moveDir.Y) * F1_VERT_SPEED, 0) or Vector3.new(0, -2, 0)
                if _abBypassPart then _abBypassPart.AssemblyLinearVelocity = hVel + vVel end
                if hDir.Magnitude > 0.5 then hum:Move(hDir.Unit, false) end
                if (targetPos - myPos).Magnitude < 6 then _autoBatSwing(char) end
            else
                hum.AutoRotate = false
                local CHASE_SPEED = AUTO_BAT.SPEED_NORMAL or 58
                local VERT_SPEED = 52
                local FOLLOW_DIST = -2
                local HEIGHT_OFFSET = 1.6
                local VERT_OFFSET = 1
                local TURN_SPEED = 285
                local MAX_TURN_RATE = 40
                local MIN_FOLLOW_DIST = 1
                local targetVel = target.AssemblyLinearVelocity
                local aimTargetPos = targetPos + (targetVel * math.clamp(targetVel.Magnitude / 130, 0.05, 0.15)) + Vector3.new(0, VERT_OFFSET, 0)
                local look = aimTargetPos - myPos
                local flatLook = Vector3.new(look.X, 0, look.Z)
                if look.Magnitude > 0.01 and flatLook.Magnitude > 0.01 then
                    local targetYaw = math.deg(math.atan2(-flatLook.X, -flatLook.Z))
                    local yawDelta = (targetYaw - root.Orientation.Y + 180) % 360 - 180
                    local targetPitch = math.deg(math.atan2(look.Y, flatLook.Magnitude))
                    local pitchDelta = (targetPitch - root.Orientation.X + 180) % 360 - 180
                    local yawRate = math.clamp(math.rad(yawDelta) * TURN_SPEED, -MAX_TURN_RATE, MAX_TURN_RATE)
                    local pitchRate = math.clamp(math.rad(pitchDelta) * TURN_SPEED, -MAX_TURN_RATE, MAX_TURN_RATE)
                    local yawRad = math.rad(root.Orientation.Y)
                    local rightAxis = Vector3.new(math.cos(yawRad), 0, -math.sin(yawRad))
                    root.AssemblyAngularVelocity = Vector3.new(0, yawRate, 0) + (rightAxis * pitchRate)
                else
                    root.AssemblyAngularVelocity = Vector3.zero
                end
                local followDist = math.max(math.abs(FOLLOW_DIST), MIN_FOLLOW_DIST)
                local dir = look.Magnitude > 0.01 and look.Unit or Vector3.new(1, 0, 0)
                local standPos = aimTargetPos - (dir * followDist) + Vector3.new(0, HEIGHT_OFFSET, 0)
                local moveDir = standPos - root.Position
                local hDir = Vector3.new(moveDir.X, 0, moveDir.Z)
                local hVel = hDir.Magnitude > 0.1 and hDir.Unit * CHASE_SPEED or Vector3.zero
                local vVel = math.abs(moveDir.Y) > 0.1 and Vector3.new(0, math.sign(moveDir.Y) * VERT_SPEED, 0) or Vector3.new(0, -2, 0)
                root.AssemblyLinearVelocity = hVel + vVel
                if hDir.Magnitude > 0.5 then hum:Move(hDir.Unit, false) end
                if (targetPos - myPos).Magnitude < 6 then _autoBatSwing(char) end
            end
        end)
    
        local function findBatForCounter()
            local c=LP.Character;if not c then return nil end
            local bp=LP:FindFirstChildOfClass("Backpack")
            for _,name in ipairs(BAT_COUNTER_SLAP_LIST) do
                local t=c:FindFirstChild(name) or (bp and bp:FindFirstChild(name));if t then return t end
            end
            for _,ch in ipairs(c:GetChildren()) do
                if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
            end
            if bp then
                for _,ch in ipairs(bp:GetChildren()) do
                    if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
                end
            end
            return nil
        end
    
        local function swingBatForCounter(bat,char)
            local hum2=char:FindFirstChildOfClass("Humanoid")
            if bat.Parent~=char then
                if hum2 then pcall(function() hum2:EquipTool(bat) end) end;task.wait(0.05)
            end
            local remote=bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
            if remote and remote:IsA("RemoteEvent") then
                pcall(function() remote:FireServer() end);task.wait(0.15);pcall(function() remote:FireServer() end)
            else
                pcall(function() bat:Activate() end);task.wait(0.15);pcall(function() bat:Activate() end)
            end
        end
    
        startBatCounter=function()
            if Conns.batCounter then return end
            Conns.batCounter=RunService.Heartbeat:Connect(function()
                if not isAlive() then Conns.batCounter:Disconnect(); Conns.batCounter=nil; return end
                if not batCounterEnabled then return end; if _Flags.batCounterDebounce then return end
                local char=LP.Character;if not char then return end; local hum2=char:FindFirstChildOfClass("Humanoid");if not hum2 then return end
                local st=hum2:GetState()
                if st==Enum.HumanoidStateType.Physics or st==Enum.HumanoidStateType.Ragdoll or st==Enum.HumanoidStateType.FallingDown then
                    _Flags.batCounterDebounce=true
                    task.spawn(function()
                        local bat=findBatForCounter();if bat then swingBatForCounter(bat,char) end
                        task.wait(0.5);_Flags.batCounterDebounce=false
                    end)
                end
            end)
        end
    
        stopBatCounter=function()
            if Conns.batCounter then Conns.batCounter:Disconnect();Conns.batCounter=nil end
            _Flags.batCounterDebounce=false
        end
    
        local function findMedusa()
            local c=LP.Character;if not c then return nil end
            for _,t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") then
                    local n=t.Name:lower();if n:find("medusa") or n:find("head") or n:find("stone") then return t end
                end
            end
            local bp=LP:FindFirstChild("Backpack")
            if bp then
                for _,t in ipairs(bp:GetChildren()) do
