        local function useMedusaCounter()
            if _MED.debounce then return end; if tick()-_MED.lastUsed<_MED.COOLDOWN then return end
            local c=LP.Character;if not c then return end; _MED.debounce=true
            local med=findMedusa();if not med then _MED.debounce=false;return end
            if med.Parent~=c then
                local hum2=c:FindFirstChildOfClass("Humanoid");if hum2 then hum2:EquipTool(med) end
            end
            pcall(function() med:Activate() end);_MED.lastUsed=tick();_MED.debounce=false
        end
    
        local function setupMedusa(char)
            for _,c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end;Conns.anchor={}
            if not char then return end
            for _,part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then
                    table.insert(Conns.anchor,part:GetPropertyChangedSignal("Anchored"):Connect(function()
                        if part.Anchored and part.Transparency==1 then useMedusaCounter() end
                    end))
                end
            end
            table.insert(Conns.anchor,char.DescendantAdded:Connect(function(part)
                if part:IsA("BasePart") then
                    table.insert(Conns.anchor,part:GetPropertyChangedSignal("Anchored"):Connect(function()
                        if part.Anchored and part.Transparency==1 then useMedusaCounter() end
                    end))
                end
            end))
        end
    
        local function stopMedusaCounter()
            for _,c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end;Conns.anchor={}
        end
    
        -- Anti Die
        local antiDieConfig = {
            healthThreshold = 25,
            healAmount = 100,
            fallDamageProtection = true,
            ragdollProtection = true,
            invincibilityFrames = 0.5,
            autoRevive = true,
        }
        local antiDieLoop = nil
        local lastHealTime = 0
        local invincibleUntil = 0
    
        local function superHeal(hum)
            if not hum then return end
            local maxHealth = hum.MaxHealth or 100
            if hum.Health >= maxHealth and hum.Health > 0 then return end
            hum.Health = maxHealth
            invincibleUntil = tick() + antiDieConfig.invincibilityFrames
            lastHealTime = tick()
            pcall(function()
                local char = hum.Parent
                if char then
                    for _, child in ipairs(char:GetChildren()) do
                        if child:IsA("NumberValue") then
                            local name = child.Name:lower()
                            if name:find("health") or name:find("hp") or name:find("life") then
                                child.Value = 100
                            end
                        end
                    end
                    if hum.Health < maxHealth then hum.Health = maxHealth end
                end
            end)
            pcall(function()
                if hum.Parent then
                    for _, child in ipairs(hum.Parent:GetChildren()) do
                        if child:IsA("BoolValue") and child.Name:lower():find("dead") then
                            child.Value = false
                        end
                    end
                end
            end)
        end
    
        local function preventDamage(root, hum)
            if not hum then return end
            if tick() < invincibleUntil then
                if hum.Health < hum.MaxHealth then hum.Health = hum.MaxHealth or 100 end
            end
            if antiDieConfig.fallDamageProtection and root then
                if root.Velocity and root.Velocity.Y < -25 then
                    root.Velocity = Vector3.new(root.Velocity.X, -3, root.Velocity.Z)
                    if hum.Health < hum.MaxHealth then superHeal(hum) end
                end
            end
            if antiDieConfig.ragdollProtection then
                local state = hum:GetState()
                if state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.FallingDown then
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                    superHeal(hum)
                    if root then
                        root.AssemblyLinearVelocity = Vector3.zero
                        root.AssemblyAngularVelocity = Vector3.zero
                    end
                end
            end
            if hum.Health <= 0 then
                superHeal(hum)
                hum:ChangeState(Enum.HumanoidStateType.Running)
                if root then
                    root.CFrame = CFrame.new(root.Position + Vector3.new(0, 2, 0))
                    root.Velocity = Vector3.zero
                end
            end
        end
    
        local function _autoReviveAntiDie()
            if not antiDieConfig.autoRevive then return end
            local char = LP.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            if hum.Health <= 0 then
                superHeal(hum)
                hum:ChangeState(Enum.HumanoidStateType.Running)
                local root = char:FindFirstChild("HumanoidRootPart")
                if root then
                    root.CFrame = CFrame.new(root.Position + Vector3.new(0, 3, 0))
                    root.Velocity = Vector3.zero
                end
            end
        end
    
        local function setupAntiDie()
            if antiDieLoop then antiDieLoop:Disconnect(); antiDieLoop = nil end
            antiDieLoop = RunService.Heartbeat:Connect(function()
                local char = LP.Character
                if not char then return end
                local hum = char:FindFirstChildOfClass("Humanoid")
                local root = char:FindFirstChild("HumanoidRootPart")
                if not hum then return end
                if hum.Health <= 0 then _autoReviveAntiDie(); return end
                if hum.Health <= antiDieConfig.healthThreshold then
                    superHeal(hum)
                    pcall(function()
                        if hum.Health < 50 then hum.Health = 100 end
                    end)
                end
                preventDamage(root, hum)
                if hum.Health < 20 and hum.Health > 0 then superHeal(hum) end
                if hum.Health <= 0 then
                    superHeal(hum)
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                    if root then
                        root.CFrame = CFrame.new(root.Position + Vector3.new(0, 2, 0))
                        root.Velocity = Vector3.zero
                    end
                end
            end)
        end
    
        local function stopAntiDie()
            if antiDieLoop then antiDieLoop:Disconnect(); antiDieLoop = nil end
        end
    
        local function monitorAntiDieHealth()
            local char = LP.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            hum:GetPropertyChangedSignal("Health"):Connect(function()
                if not tpBatEnabled then return end
                if hum.Health <= 0 then
                    superHeal(hum)
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                    task.wait(0.05)
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        root.CFrame = CFrame.new(root.Position + Vector3.new(0, 3, 0))
                        root.Velocity = Vector3.zero
                    end
                end
            end)
        end
    
        -- TP Bat
        local _tpBat_h, _tpBat_hrp = nil, nil
        local _TP_RANGE = 3.5
        local _TP_LEAD = 0.08
    
        local function _tpBatGetBat()
            local char=LP.Character; if not char then return nil end
            local tool=char:FindFirstChild("Bat"); if tool then return tool end
            local bp2=LP:FindFirstChild("Backpack")
            if bp2 then
                tool=bp2:FindFirstChild("Bat"); if tool then tool.Parent=char; return tool end
            end
            return nil
        end
    
        local function _tpBatTryHit()
            if tpBatHittingCooldown then return end; tpBatHittingCooldown=true
            pcall(function()
                local bat=_tpBatGetBat(); if bat then
                    bat:Activate()
                    local ev=bat:FindFirstChildWhichIsA("RemoteEvent")
                    if ev then ev:FireServer(); ev:FireServer() end
                end
            end)
            task.delay(0.06 + math.random()*0.05, function() tpBatHittingCooldown=false end)
        end
    
        local function _tpBatGetClosest()
            if not _tpBat_hrp then return nil,math.huge end
            local cp,cd=nil,math.huge
            for _,p in pairs(Players:GetPlayers()) do
                if p~=LP and p.Character then
                    local hum=p.Character:FindFirstChildOfClass("Humanoid")
                    local tr=p.Character:FindFirstChild("HumanoidRootPart")
                    if tr and hum and hum.Health>0 then
                        local d=(_tpBat_hrp.Position-tr.Position).Magnitude
                        if d<cd then cd=d; cp=p end
                    end
                end
            end
            return cp,cd
        end
    
        local function _tpBatSetupChar(char)
            task.wait(0.1)
            _tpBat_h=char:WaitForChild("Humanoid",5); _tpBat_hrp=char:WaitForChild("HumanoidRootPart",5)
        end
    
        rawConn(RunService.Heartbeat, function()
            if not (tpBatEnabled and _tpBat_h and _tpBat_hrp) then return end
            local target,_ = _tpBatGetClosest()
            if not (target and target.Character) then return end
            local tr=target.Character:FindFirstChild("HumanoidRootPart"); if not tr then return end
            local vel = tr.AssemblyLinearVelocity
            local future = tr.Position + Vector3.new(vel.X*_TP_LEAD, 0, vel.Z*_TP_LEAD)
            local aimPos = future + Vector3.new(0, 0.9, 0)
            if (_tpBat_hrp.Position - aimPos).Magnitude > _TP_RANGE then
                local lookDir = (tr.Position - aimPos)
                local facing = lookDir.Magnitude > 0.01 and CFrame.lookAt(aimPos, tr.Position) or CFrame.new(aimPos)
                _tpBat_hrp.CFrame = facing
            end
            pcall(function()
                if sethiddenproperty then sethiddenproperty(_tpBat_hrp,"PhysicsRepRootPart",tr) end
            end)
            local cam=workspace.CurrentCamera
            cam.CFrame=CFrame.new(cam.CFrame.Position,tr.Position)
            _tpBatTryHit()
        end)
    
        local function startTpBat()
            local char=LP.Character; if char then _tpBatSetupChar(char) end
            setupAntiDie(); monitorAntiDieHealth()
        end
    
        local function stopTpBat()
            tpBatEnabled=false; stopAntiDie()
        end
    
