            local CRN_T = 2
            local BAR_T = 3
            local BAR_BG_T = 5
            local TXT_NAME = 13
            local TXT_INFO = 11
    
            local function hpColor(pct)
                pct = math.clamp(pct, 0, 1)
                return Color3.fromRGB(255, math.floor(pct * 255), math.floor(pct * 255))
            end
    
            local function newBundle()
                local b = {}
                for i = 1, 8 do
                    local ln = Drawing.new("Line")
                    ln.Thickness = CRN_T
                    ln.Color = WHITE
                    ln.Transparency = 1
                    ln.Visible = false
                    b[i] = ln
                end
                local hBG = Drawing.new("Line")
                hBG.Thickness = BAR_BG_T
                hBG.Color = NEARBLK
                hBG.Transparency = 0.55
                hBG.Visible = false
                b[9] = hBG
                local hFG = Drawing.new("Line")
