                return bg
            end
    
            local function hideBundle(b)
                for i = 1, 13 do b[i].Visible = false end
            end
    
            local function hidePlayer(player)
                if ESP[player] then hideBundle(ESP[player]) end
                if BBList[player] then BBList[player].Enabled = false end
            end
    
            local function updateESP()
                local cam = workspace.CurrentCamera
                local vp = cam.ViewportSize
                local myChar = LP.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not OPT.enabled then
                    for _, p in ipairs(Players:GetPlayers()) do hidePlayer(p) end
                    return
                end
                for _, player in ipairs(Players:GetPlayers()) do
                    if player == LP then continue end
                    local char = player.Character
                    if not char then hidePlayer(player); continue end
                    local root = char:FindFirstChild("HumanoidRootPart")
                    local head = char:FindFirstChild("Head")
                    if not root or not head then hidePlayer(player); continue end
                    local rVP, onScreen = cam:WorldToViewportPoint(root.Position)
                    if not onScreen or rVP.Z <= 0 then hidePlayer(player); continue end
                    local hVP = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 0.65, 0))
                    if not ESP[player] then ESP[player] = newBundle() end
                    local b = ESP[player]
                    local boxH = math.abs(hVP.Y - rVP.Y) * 1.9
                    local boxW = boxH * 0.52
                    local cx = rVP.X
                    local top = rVP.Y - boxH * 0.52
                    local bot = top + boxH
                    local lft = cx - boxW * 0.5
                    local rgt = cx + boxW * 0.5
                    local cH = boxW * CRN
                    local cV = boxH * CRN
    
                    if OPT.showBox then
                        b[1].From=Vector2.new(lft,top); b[1].To=Vector2.new(lft+cH,top)
                        b[2].From=Vector2.new(lft,top); b[2].To=Vector2.new(lft,top+cV)
                        b[3].From=Vector2.new(rgt,top); b[3].To=Vector2.new(rgt-cH,top)
                        b[4].From=Vector2.new(rgt,top); b[4].To=Vector2.new(rgt,top+cV)
                        b[5].From=Vector2.new(lft,bot); b[5].To=Vector2.new(lft+cH,bot)
                        b[6].From=Vector2.new(lft,bot); b[6].To=Vector2.new(lft,bot-cV)
                        b[7].From=Vector2.new(rgt,bot); b[7].To=Vector2.new(rgt-cH,bot)
                        b[8].From=Vector2.new(rgt,bot); b[8].To=Vector2.new(rgt,bot-cV)
                        for i=1,8 do b[i].Visible=true end
                    else
                        for i=1,8 do b[i].Visible=false end
                    end
    
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if OPT.showHealth then
                        local pct = hum and math.clamp(hum.Health/math.max(hum.MaxHealth,1),0,1) or 1
                        local bx = lft - 5
                        b[9].From=Vector2.new(bx,top); b[9].To=Vector2.new(bx,bot); b[9].Visible=true
                        b[10].From=Vector2.new(bx,bot); b[10].To=Vector2.new(bx,bot-boxH*pct)
                        b[10].Color=hpColor(pct); b[10].Visible=true
                    else
                        b[9].Visible=false; b[10].Visible=false
                    end
    
                    if OPT.showTracer then
                        b[11].From=Vector2.new(vp.X*0.5,vp.Y); b[11].To=Vector2.new(cx,bot); b[11].Visible=true
                    else
                        b[11].Visible=false
                    end
    
                    if OPT.showNames then
                        b[12].Text=player.DisplayName; b[12].Position=Vector2.new(cx,top-15); b[12].Visible=true
                    else
                        b[12].Visible=false
                    end
    
                    if OPT.showDist then
                        local hp = hum and math.floor(hum.Health) or 100
                        local mhp = hum and math.max(hum.MaxHealth,1) or 100
                        local dist = myRoot and math.floor((myRoot.Position-root.Position).Magnitude) or 0
                        b[13].Text=hp.."/"..mhp.." · "..dist.."m"
                        b[13].Position=Vector2.new(cx,bot+3); b[13].Visible=true
                    else
                        b[13].Visible=false
                    end
    
                    if OPT.showAvatar then
                        local bb = getAvatar(player)
                        bb.Adornee = head; bb.Enabled = true
                    elseif BBList[player] then
                        BBList[player].Enabled=false
                    end
                end
            end
    
            do
                local _espAcc = 0
                rawConn(RunService.Heartbeat, function(dt)
                    _espAcc = _espAcc + dt
                    if _espAcc < 0.05 then return end
                    _espAcc = 0
                    updateESP()
                end)
            end
    
            Players.PlayerRemoving:Connect(function(plr)
                if ESP[plr] then
                    for _, o in pairs(ESP[plr]) do pcall(function() o:Remove() end) end
                    ESP[plr] = nil
                end
                if BBList[plr] then BBList[plr]:Destroy(); BBList[plr]=nil end
            end)
        end)()
    
