                local id = _bgImages[bgIndex]
                local imageObject = _AMIRI._BgImage
    
                if imageObject and imageObject.Parent then
                    imageObject.Image = "rbxassetid://" .. id
                    imageObject.Visible = true
                    imageObject.ImageTransparency = 0
                    imageObject.ZIndex = 0
                end
    
                _configState["backgroundImageIndex"] = bgIndex
                _autoSaveConfig()
    
                -- Update selector borders so only the selected image is bright.
                for i, item in ipairs(buttons) do
                    local selected = (i == bgIndex)
                    item.stroke.Color = selected
                        and Color3.fromRGB(255, 255, 255)
                        or Color3.fromRGB(70, 70, 75)
                    item.stroke.Thickness = selected and 2.5 or 1.25
                    item.image.ImageTransparency = selected and 0 or 0.08
                end
            end
    
            for i, id in ipairs(previewIds) do
                local btn = Instance.new("ImageButton")
                btn.Name = "Image" .. i
                btn.Size = UDim2.new(0, 76, 0, 48)
                btn.BackgroundColor3 = Color3.fromRGB(18, 18, 20)
                btn.BackgroundTransparency = 0
                btn.BorderSizePixel = 0
                btn.Image = "rbxassetid://" .. id
                btn.ScaleType = Enum.ScaleType.Crop
                btn.AutoButtonColor = false
                btn.ZIndex = 8
                btn.Parent = previewHolder
                addCorner(btn, 7)
    
                local stroke = Instance.new("UIStroke")
                stroke.Color = Color3.fromRGB(70, 70, 75)
                stroke.Thickness = 1.25
                stroke.Transparency = 0
                stroke.Parent = btn
    
                -- No number/text badge over the background thumbnails.
                buttons[i] = {
                    button = btn,
                    image = btn,
                    stroke = stroke
                }
    
                btn.MouseButton1Click:Connect(function()
                    bgIndex = i
                    applyBackground()
                end)
            end
    
            applyBackground()
        end)()
    
