        _AMIRI.B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        _AMIRI.setFontUI = nil
    
        function _AMIRI.encode(s)
            local r, pad = {}, ""
            local n = #s % 3
            if n > 0 then s = s .. string.rep("\0", 3 - n); pad = string.rep("=", 3 - n) end
            for i = 1, #s, 3 do
                local a, b, c = string.byte(s, i, i + 2)
                local v = bit32.bor(bit32.lshift(a, 16), bit32.lshift(b, 8), c)
                r[#r+1] = _AMIRI.B64:sub(bit32.rshift(v, 18) + 1, bit32.rshift(v, 18) + 1)
                r[#r+1] = _AMIRI.B64:sub(bit32.band(bit32.rshift(v, 12), 63) + 1, bit32.band(bit32.rshift(v, 12), 63) + 1)
                r[#r+1] = _AMIRI.B64:sub(bit32.band(bit32.rshift(v, 6), 63) + 1, bit32.band(bit32.rshift(v, 6), 63) + 1)
                r[#r+1] = _AMIRI.B64:sub(bit32.band(v, 63) + 1, bit32.band(v, 63) + 1)
            end
            local out = table.concat(r)
            return out:sub(1, #out - #pad) .. pad
        end
    
        function _AMIRI.decode(s)
            local t = {}
            for i = 1, #_AMIRI.B64 do t[_AMIRI.B64:sub(i, i)] = i - 1 end
            s = s:gsub("[^A-Za-z0-9+/=]", "")
            local r = {}
            for i = 1, #s, 4 do
                local a = t[s:sub(i, i )] or 0
                local b = t[s:sub(i+1, i+1)] or 0
                local c = t[s:sub(i+2, i+2)] or 0
                local d = t[s:sub(i+3, i+3)] or 0
                local v = bit32.bor(bit32.lshift(a, 18), bit32.lshift(b, 12), bit32.lshift(c, 6), d)
                r[#r+1] = string.char(bit32.rshift(v, 16))
                if s:sub(i+2, i+2) ~= "=" then r[#r+1] = string.char(bit32.band(bit32.rshift(v, 8), 0xFF)) end
                if s:sub(i+3, i+3) ~= "=" then r[#r+1] = string.char(bit32.band(v, 0xFF)) end
            end
            return table.concat(r)
        end
    
        _AMIRI.cfgPack = {
            fontIdx="a1",menuW="a2",menuH="a3",
            menuXScale="a4",menuXOffset="a5",menuYScale="a6",menuYOffset="a7",
            normalSpeed="a8",carrySpeed_val="a9",laggerSpeed="b0",laggerCarrySpeed="b1",
            tpHeight="b2",v1Radius="b3",v2StealRadius="b4",fbBtnSize="b5",
            infJumpMode="b6",hudBarXScale="b7",hudBarYScale="b8",hudBarXOffset="b9",
            hudBarYOffset="c0",dragLocked="c2",
            AUTOLEFT="c3",AUTORIGHT="c4",AUTOTP="c5",AUTOCARRY="c6",
            AUTOSTEAL="c7",AUTOGRABV2="c8", CARRYBYPASS="d1",LAGMODE="d2",
            ANTILAG="d3",ANTIDIE="d9",ANTIRAGDOLL="d4",INFJUMP="d5",DARKMODE="d6",
            FOV120="d7",STRETCHREZ="d8",ESPPLAYER="e1",VAMPIREANM="e2",
            AUTOBAT="e3", TPBAT="e4", CARRYSPEED="e5", LAGGERSPEED="e6", LAGGER_CARRY="e7",
            DROP="e8", TPDOWN="e9", VIZFPS="f0",
            MIRRORTP="m1",  -- add mirror tp key
        }
        _AMIRI.cfgUpack = {}
        for k,v in pairs(_AMIRI.cfgPack) do _AMIRI.cfgUpack[v]=k end
    
        local function _cfgPK(k)
            if _AMIRI.cfgPack[k] then return _AMIRI.cfgPack[k] end
            local s=k:match("^btnVis_(.+)$");if s then return "V"..s end
            s=k:match("^kb_(.+)$");if s then return "K"..s end
            s=k:match("^btnPos_(.+)$");if s then return "P"..s end
            return k
        end
        local function _cfgUK(k)
            if _AMIRI.cfgUpack[k] then return _AMIRI.cfgUpack[k] end
            local s=k:match("^V(.+)$");if s then return "btnVis_"..s end
            local s=k:match("^K(.+)$");if s then return "kb_"..s end
            local s=k:match("^P(.+)$");if s then return "btnPos_"..s end
            return k
        end
    
        _AMIRI.packCfg=function(t)
            local r={};for k,v in pairs(t) do r[_cfgPK(k)]=v end;return r
        end
        _AMIRI.unpackCfg=function(t)
            local r={};for k,v in pairs(t) do r[_cfgUK(k)]=v end;return r
        end
    
