                local impStroke, _ = addNeonStroke(impRow, 1, Color3.fromRGB(80,80,80), Color3.fromRGB(80,80,80))
    
                local impTitle = Instance.new("TextLabel", impRow)
                impTitle.Size = UDim2.new(1,-24,0,14)
                impTitle.Position = UDim2.new(0,12,0,7)
                impTitle.BackgroundTransparency = 1
                impTitle.Text = "IMPORT CONFIG"
                impTitle.TextColor3 = Color3.fromRGB(255,255,255)
                impTitle.TextSize = 12
                impTitle.Font = Enum.Font.GothamBold
                impTitle.TextXAlignment = Enum.TextXAlignment.Left
                impTitle.ZIndex = 5
    
                local impBox = Instance.new("TextBox", impRow)
                impBox.Size = UDim2.new(1,-84,0,24)
                impBox.Position = UDim2.new(0,12,0,28)
                impBox.BackgroundColor3 = Color3.fromRGB(50,50,50)
                impBox.BorderSizePixel = 0
                impBox.Text = ""
                impBox.PlaceholderText = "AMIRI-XXXXXX"
                impBox.PlaceholderColor3 = Color3.fromRGB(150,150,150)
                impBox.TextColor3 = Color3.fromRGB(255,255,255)
                impBox.TextSize = 11
                impBox.Font = Enum.Font.GothamBold
                impBox.ClearTextOnFocus = false
                impBox.ZIndex = 6
                addCorner(impBox, 5)
                local impBoxStroke, setImpBoxActive = addNeonStroke(impBox, 1, Color3.fromRGB(80,80,80), Color3.fromRGB(150,150,150))
    
                local impBtn = Instance.new("TextButton", impRow)
                impBtn.Size = UDim2.new(0,60,0,24)
                impBtn.Position = UDim2.new(1,-70,0,28)
                impBtn.BackgroundColor3 = Color3.fromRGB(80,80,80)
                impBtn.BorderSizePixel = 0
                impBtn.Text = "IMPORT"
                impBtn.TextColor3 = Color3.fromRGB(255,255,255)
                impBtn.TextSize = 11
                impBtn.Font = Enum.Font.GothamBold
                impBtn.ZIndex = 6
                addCorner(impBtn, 5)
                local impBtnStroke, setImpBtnActive = addNeonStroke(impBtn, 1, Color3.fromRGB(150,150,150), Color3.fromRGB(255,255,255))
    
                local impStatus = Instance.new("TextLabel", impRow)
                impStatus.Size = UDim2.new(1,-24,0,10)
                impStatus.Position = UDim2.new(0,12,1,-11)
                impStatus.BackgroundTransparency = 1
                impStatus.Text = ""
                impStatus.TextColor3 = Color3.fromRGB(255,0,0)
                impStatus.TextSize = 9
                impStatus.Font = Enum.Font.GothamBold
                impStatus.TextXAlignment = Enum.TextXAlignment.Left
                impStatus.ZIndex = 5
    
                local impBusy = false
                impBtn.MouseButton1Click:Connect(function()
                    if impBusy then return end
                    local raw = impBox.Text:gsub("%s+", "")
                    if raw == "" then
                        impStatus.TextColor3 = Color3.fromRGB(255,0,0)
                        impStatus.Text = "ENTER A CODE FIRST."
                        return
                    end
                    impBusy = true
                    impBtn.Text = "..."
                    impStatus.Text = ""
                    local ok, saved = pcall(function()
                        local encoded = raw:match("^[Aa][Mm][Ii][Rr][Ii]%-(.+)$") or raw
                        return _AMIRI.unpackCfg(HS:JSONDecode(_AMIRI.decode(encoded)))
                    end)
                    if ok and type(saved) == "table" then
                        for _, entry in ipairs(_toggleRegistry) do
                            local on = saved[entry.key]
                            if on ~= nil then
                                entry.setState(on)
                                _configState[entry.key] = on
                                if entry.callback then pcall(entry.callback, on) end
                            end
                        end
                        if saved.fontIdx ~= nil then
                            _currentFontIdx = math.max(1, math.min(#_FONTS, saved.fontIdx))
                            applyFontToGui()
                            _configState.fontIdx = _currentFontIdx
                            if _AMIRI.setFontUI then _AMIRI.setFontUI() end
                        end
                        if saved.infJumpMode then
                            local mode = saved.infJumpMode
                            if mode == "manual" or mode == "hold" then
                                infJumpMode = mode
                                if _AMIRI.updateJumpModeUI then _AMIRI.updateJumpModeUI(mode) end
                            end
                        end
                        if saved.keybinds and type(saved.keybinds) == "table" then
                            _configState["keybinds"] = saved.keybinds
                            _AMIRI._keybinds = saved.keybinds
                        end
                        _autoSaveConfig()
                        impBox.Text = ""
                        impStatus.TextColor3 = Color3.fromRGB(0,255,0)
                        impStatus.Text = "CONFIG APPLIED!"
                        task.wait(3)
                        impStatus.Text = ""
                    else
                        impStatus.TextColor3 = Color3.fromRGB(255,0,0)
                        impStatus.Text = "INVALID CONFIG CODE."
                        task.wait(3)
                        impStatus.Text = ""
                    end
                    impBtn.Text = "IMPORT"
                    impBusy = false
                end)
            end
    
            -- KEYBINDS SECTION
            local p = tabPages["KEYBIND"]
            sectionLabel(p, "KEYBINDS", 130)
    
            local keybindRegistry = {}
            local function getKeybind(featureKey)
                if not _configState["keybinds"] then _configState["keybinds"] = {} end
                return _configState["keybinds"][featureKey] or ""
            end
            local function setKeybind(featureKey, keyName)
                if not _configState["keybinds"] then _configState["keybinds"] = {} end
                if keyName == "" then
                    _configState["keybinds"][featureKey] = nil
                else
                    _configState["keybinds"][featureKey] = keyName
                end
                _AMIRI._keybinds = _configState["keybinds"]
                _autoSaveConfig()
            end
    
            local function createKeybindRow(featureKey, labelText, order)
                local Row = Instance.new("Frame")
                Row.Size = UDim2.new(1,0,0,40)
                Row.BackgroundColor3 = Color3.fromRGB(30,30,30)
                Row.BackgroundTransparency = 0.85
                Row.BorderSizePixel = 0
                Row.LayoutOrder = order
                Row.Parent = p
                addCorner(Row, 10)
                local rowStroke, _ = addNeonStroke(Row, 1, Color3.fromRGB(80,80,80), Color3.fromRGB(80,80,80))
    
                local rowLabel = Instance.new("TextLabel", Row)
                rowLabel.Size = UDim2.new(0.5,0,0,16)
                rowLabel.Position = UDim2.new(0,12,0,8)
                rowLabel.BackgroundTransparency = 1
                rowLabel.Text = labelText
                rowLabel.TextColor3 = Color3.fromRGB(255,255,255)
                rowLabel.TextSize = 12
                rowLabel.Font = Enum.Font.GothamBold
                rowLabel.TextXAlignment = Enum.TextXAlignment.Left
                rowLabel.ZIndex = 5
    
                local ul = Instance.new("Frame", Row)
                ul.Size = UDim2.new(0, math.min(#labelText * 5.8, 150), 0, 1)
                ul.Position = UDim2.new(0,12,0,25)
                ul.BackgroundColor3 = Color3.fromRGB(255,255,255)
                ul.BackgroundTransparency = 0.6
                ul.BorderSizePixel = 0
                addCorner(ul, 1)
    
                local keyBtn = Instance.new("TextButton", Row)
                keyBtn.Size = UDim2.new(0, 80, 0, 24)
                keyBtn.Position = UDim2.new(1, -90, 0.5, -12)
                keyBtn.BackgroundColor3 = Color3.fromRGB(50,50,50)
                keyBtn.BorderSizePixel = 0
                keyBtn.Text = ""
                keyBtn.TextColor3 = Color3.fromRGB(255,255,255)
                keyBtn.TextSize = 10
                keyBtn.Font = Enum.Font.GothamBold
                keyBtn.ZIndex = 6
                addCorner(keyBtn, 5)
                local keyBtnStroke, setKeyBtnActive = addNeonStroke(keyBtn, 1.5, Color3.fromRGB(80,80,80), Color3.fromRGB(200,200,200))
    
                local curBind = getKeybind(featureKey)
                keyBtn.Text = curBind ~= "" and curBind or "NONE"
    
                local listening = false
                local listenConn = nil
                local function startListening()
                    if listening then return end
                    listening = true
                    keyBtn.Text = "PRESS KEY..."
                    keyBtn.BackgroundColor3 = Color3.fromRGB(100,100,100)
                    setKeyBtnActive(true)
                    if listenConn then listenConn:Disconnect() end
                    listenConn = UIS.InputBegan:Connect(function(input)
                        if not listening then return end
                        if input.UserInputType == Enum.UserInputType.Keyboard 
                           or string.find(input.UserInputType.Name, "Gamepad") then
                            local key = input.KeyCode.Name
                            if key ~= "Unknown" then
                                setKeybind(featureKey, key)
                                keyBtn.Text = key
                                listening = false
                                if listenConn then listenConn:Disconnect(); listenConn = nil end
                                keyBtn.BackgroundColor3 = Color3.fromRGB(50,50,50)
                                setKeyBtnActive(false)
                            end
                        end
                    end)
                end
    
                keyBtn.MouseButton1Click:Connect(function()
                    if listening then
                        listening = false
                        if listenConn then listenConn:Disconnect(); listenConn = nil end
                        keyBtn.Text = getKeybind(featureKey) or "NONE"
                        keyBtn.BackgroundColor3 = Color3.fromRGB(50,50,50)
                        setKeyBtnActive(false)
                    else
                        startListening()
                    end
                end)
    
                local clearBtn = Instance.new("TextButton", Row)
                clearBtn.Size = UDim2.new(0, 24, 0, 24)
                clearBtn.Position = UDim2.new(1, -24, 0.5, -12)
                clearBtn.BackgroundColor3 = Color3.fromRGB(80,80,80)
                clearBtn.BorderSizePixel = 0
                clearBtn.Text = "X"
                clearBtn.TextColor3 = Color3.fromRGB(255,255,255)
                clearBtn.TextSize = 10
                clearBtn.Font = Enum.Font.GothamBold
                clearBtn.ZIndex = 6
                addCorner(clearBtn, 5)
                local clearBtnStroke, setClearActive = addNeonStroke(clearBtn, 1, Color3.fromRGB(150,150,150), Color3.fromRGB(255,255,255))
                clearBtn.MouseButton1Click:Connect(function()
                    if listening then
                        listening = false
                        if listenConn then listenConn:Disconnect(); listenConn = nil end
                        keyBtn.BackgroundColor3 = Color3.fromRGB(50,50,50)
                        setKeyBtnActive(false)
                    end
                    setKeybind(featureKey, "")
                    keyBtn.Text = "NONE"
                end)
    
                hoverRow(Row, ROW_ALPHA)
                table.insert(keybindRegistry, {key=featureKey, btn=keyBtn})
            end
    
            local featureNames = {
                AUTOLEFT   = "Auto Left",
                AUTORIGHT  = "Auto Right",
                AUTOBAT    = "Aimbot",
                DROP       = "Drop",
                TPDOWN     = "TP Down",
                CARRYSPEED = "Carry Speed",
                LAGGERSPEED = "Lagger Speed",
                LAGGER_CARRY = "Lagger Carry",
                TPBAT      = "TP Bat",
                VIZFPS     = "Viz FPS",
                MIRRORTP   = "Mirror TP",   -- add keybind
            }
    
            local keyOrder = 131
            for key, name in pairs(featureNames) do
                createKeybindRow(key, name, keyOrder)
                keyOrder = keyOrder + 1
            end
    
            _regToggleOnly("AUTOLEFT", autoLeftEnabled, function(on)
                autoLeftEnabled = on
                if on then
                    if autoRightEnabled then autoRightEnabled=false; stopAutoRight(); if _AMIRI._setAROn then _AMIRI._setAROn(false) end end
                    if autoBatEnabled then disableAutoBat() end
                    startAutoLeft()
                else
                    stopAutoLeft()
                end
                if _AMIRI._setALOn then _AMIRI._setALOn(on) end
            end)
            _regToggleOnly("AUTORIGHT", autoRightEnabled, function(on)
                autoRightEnabled = on
                if on then
                    if autoLeftEnabled then autoLeftEnabled=false; stopAutoLeft(); if _AMIRI._setALOn then _AMIRI._setALOn(false) end end
                    if autoBatEnabled then disableAutoBat() end
                    startAutoRight()
                else
                    stopAutoRight()
                end
                if _AMIRI._setAROn then _AMIRI._setAROn(on) end
            end)
            _regToggleOnly("AUTOBAT", autoBatEnabled, function(on)
                if on then enableAutoBat() else disableAutoBat() end
            end)
            _regToggleOnly("TPBAT", tpBatEnabled, function(on)
                tpBatEnabled = on
                if on then startTpBat() else stopTpBat() end
                if _AMIRI._setTPBOn then _AMIRI._setTPBOn(on) end
            end)
            _regToggleOnly("CARRYSPEED", speedMode, function(on)
                speedMode = on
                if laggerToggled then laggerToggled = false end
                if _AMIRI._setCarryFB then _AMIRI._setCarryFB(on) end
            end)
            _regToggleOnly("LAGGERSPEED", laggerToggled and laggerPhase==0, function(on)
                if on then
                    laggerToggled = true
                    laggerPhase = 0
                    speedMode = false
                else
                    laggerToggled = false
                    laggerPhase = 0
                    speedMode = true
                end
                if _AMIRI._setLaggerFB then _AMIRI._setLaggerFB(on) end
                if _AMIRI._setCarryFB then _AMIRI._setCarryFB(speedMode) end
                if _AMIRI._setLagFB then _AMIRI._setLagFB(false) end
            end)
            _regToggleOnly("LAGGER_CARRY", laggerToggled and laggerPhase==2, function(on)
                if on then
                    laggerToggled = true
                    laggerPhase = 2
                    speedMode = false
                else
                    laggerToggled = false
                    laggerPhase = 0
                    speedMode = true
                end
                if _AMIRI._setLagFB then _AMIRI._setLagFB(on) end
                if _AMIRI._setCarryFB then _AMIRI._setCarryFB(speedMode) end
                if _AMIRI._setLaggerFB then _AMIRI._setLaggerFB(false) end
            end)
    
            _regAction("DROP", "Drop", function() runDrop() end)
            _regAction("TPDOWN", "TP Down", function() runTPFloor() end)
    
            rawConn(UIS.InputBegan, function(input)
                if input.UserInputType == Enum.UserInputType.Keyboard 
                   or string.find(input.UserInputType.Name, "Gamepad") then
                    local keyName = input.KeyCode.Name
                    if keyName == "Unknown" then return end
                    if not _AMIRI._keybinds then return end
                    for featureKey, boundKey in pairs(_AMIRI._keybinds) do
                        if boundKey == keyName then
                            local action = _AMIRI._actionRegistry[featureKey]
                            if action then
                                pcall(action.fn)
                                break
                            end
                            for _, entry in ipairs(_toggleRegistry) do
                                if entry.key == featureKey then
                                    local newState = not _configState[featureKey]
                                    entry.setState(newState)
                                    _configState[featureKey] = newState
                                    if entry.callback then pcall(entry.callback, newState) end
                                    _autoSaveConfig()
                                    break
                                end
                            end
                            break
                        end
                    end
                end
            end)
        end)()
    
        do
            _AMIRI._setTPBOn = nil
            _AMIRI._setCarryFB = nil
            _AMIRI._setLaggerFB = nil
            _AMIRI._setLagFB = nil
        end
    
        -- ============================================================
        -- MIRROR TP DOWN HEARTBEAT (added as rawConn)
        -- ============================================================
        rawConn(RunService.Heartbeat, function()
            if not mirrorTPDownEnabled then
                -- clear tracking when disabled
                for k in pairs(mirrorTPPreviousY) do mirrorTPPreviousY[k] = nil end
                return
            end
            local aimbotActive = autoBatEnabled or bypassAimbotToggled
            if not aimbotActive then
                for k in pairs(mirrorTPPreviousY) do mirrorTPPreviousY[k] = nil end
                return
            end
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr == LP then continue end
                local char = plr.Character
                if not char then continue end
                local root = char:FindFirstChild("HumanoidRootPart")
                if not root then continue end
                local currentY = root.Position.Y
                local prev = mirrorTPPreviousY[plr.UserId]
                if prev and (prev - currentY) >= DROP_THRESHOLD then
                    -- teleport down
                    local myChar = LP.Character
                    if myChar then
                        local myRoot = myChar:FindFirstChild("HumanoidRootPart")
                        local myHum = myChar:FindFirstChildOfClass("Humanoid")
                        if myRoot and myHum and myHum.Health > 0 then
                            local now = tick()
                            if now - mirrorTPLastTime >= MIRROR_TP_COOLDOWN then
                                mirrorTPLastTime = now
                                local offsetX = (math.random() - 0.5) * 0.4
                                local offsetZ = (math.random() - 0.5) * 0.4
                                local y = TELEPORT_Y + (math.random() * 0.6 - 0.3)
                                myRoot.CFrame = CFrame.new(myRoot.Position.X + offsetX, y, myRoot.Position.Z + offsetZ)
                                myRoot.AssemblyLinearVelocity = Vector3.new(offsetX * 0.5, 0, offsetZ * 0.5)
                            end
                        end
                    end
                    -- reset tracking to avoid spam
                    mirrorTPPreviousY = {}
                    break
                end
                mirrorTPPreviousY[plr.UserId] = currentY
            end
        end)
    
        task.spawn(function()
            do
                -- Load saved menu position or use default (centered, raised)
                local saved = loadConfig()
                local menuXScale = saved["menuXScale"]
                local menuXOffset = saved["menuXOffset"]
                local menuYScale = saved["menuYScale"]
                local menuYOffset = saved["menuYOffset"]
                if menuXOffset ~= nil and menuYOffset ~= nil then
                    Container.Position = UDim2.new(menuXScale or 0, menuXOffset, menuYScale or 0, menuYOffset)
                else
                    Container.Position = UDim2.new(0.5, -180, 0.5, -260) -- default: centered, raised
                end
            end
            task.wait(0.5)
            if not isAlive() then return end
            local saved = loadConfig()
            if not next(saved) then applyFontToGui(); return end
    
            for _, entry in ipairs(_toggleRegistry) do
                local on = saved[entry.key]
                if on then
                    entry.setState(true)
                    _configState[entry.key] = true
                    if entry.callback then pcall(entry.callback, true) end
                end
            end
    
            if saved["dropMode"] then
                dropMode = saved["dropMode"]
                if _AMIRI._refreshDropModeChips then _AMIRI._refreshDropModeChips() end
            end
            if saved["fontIdx"] ~= nil then
                _currentFontIdx = math.max(1, math.min(#_FONTS, saved["fontIdx"]))
                applyFontToGui()
                _configState["fontIdx"] = saved["fontIdx"]
                if _AMIRI.setFontUI then _AMIRI.setFontUI() end
            end
            if saved["menuW"] and type(saved["menuW"]) == "number" then
                local w = math.clamp(saved["menuW"], _AMIRI.MENU_MIN_W, _AMIRI.MENU_MAX_W)
                local h = math.clamp(saved["menuH"] or 520, _AMIRI.MENU_MIN_H, _AMIRI.MENU_MAX_H)
                Container.Size = UDim2.new(0, w, 0, h)
            else
                Container.Size = UDim2.new(0, 360, 0, 520)
            end
            if saved["fbBtnSize"] and type(saved["fbBtnSize"]) == "number" then
                task.delay(0.3, function()
                    if _AMIRI._setFbSize then _AMIRI._setFbSize(math.clamp(saved["fbBtnSize"], 35, 120)) end
                end)
            end
            if saved["infJumpMode"] then
                local mode = saved["infJumpMode"]
                if mode == "manual" or mode == "hold" then
                    infJumpMode = mode
                    if _AMIRI.updateJumpModeUI then _AMIRI.updateJumpModeUI(mode) end
                end
            end
            if saved["normalSpeed"] then
                NS = saved["normalSpeed"]; if _AMIRI._speedSetters then _AMIRI._speedSetters.ns(NS) end
            end
            if saved["carrySpeed_val"] then
                CS = saved["carrySpeed_val"]; if _AMIRI._speedSetters then _AMIRI._speedSetters.cs(CS) end
            end
            if saved["laggerSpeed"] then
                LAGGER_SPEED = saved["laggerSpeed"]; if _AMIRI._speedSetters then _AMIRI._speedSetters.ls(LAGGER_SPEED) end
            end
            if saved["laggerCarrySpeed"] then
                LAGGER_CARRY_SPEED = saved["laggerCarrySpeed"]; if _AMIRI._speedSetters then _AMIRI._speedSetters.lcs(LAGGER_CARRY_SPEED) end
            end
            if saved["v1Radius"] then
                Steal.StealRadius=saved["v1Radius"]; if _AMIRI._mechSetters and _AMIRI._mechSetters.stealR then _AMIRI._mechSetters.stealR(saved["v1Radius"]) end
            end
            AG_CONFIG.V2_PRIME_RANGE = 61
            if saved["v2StealRadius"] then
                AG_CONFIG.V2_STEAL_RANGE=saved["v2StealRadius"]; if _AMIRI._mechSetters and _AMIRI._mechSetters.v2SR then _AMIRI._mechSetters.v2SR(saved["v2StealRadius"]) end
            end
            if saved["tpHeight"] then
                autoTPHeight = saved["tpHeight"]; if _AMIRI._mechSetters then _AMIRI._mechSetters.tph(saved["tpHeight"]) end
            end
            if saved["batSpeedNormal"] then
                AUTO_BAT.SPEED_NORMAL = saved["batSpeedNormal"]; if _AMIRI._batSpeedSetters then _AMIRI._batSpeedSetters.normal(saved["batSpeedNormal"]) end
            end
            if saved["batSpeedBypass"] then
                AUTO_BAT.SPEED_BYPASS = saved["batSpeedBypass"]; if _AMIRI._batSpeedSetters then _AMIRI._batSpeedSetters.bypass(saved["batSpeedBypass"]) end
            end
            if saved["autoBatMode"] then
                autoBatMode = saved["autoBatMode"]; if _AMIRI._refreshAimbotModeChips then _AMIRI._refreshAimbotModeChips() end
            end
            if saved["keybinds"] and type(saved["keybinds"]) == "table" then
                _AMIRI._keybinds = saved["keybinds"]
            end
    
            if saved["VIZFPS"] ~= nil then
                vizFpsEnabled = saved["VIZFPS"]
                applyVizFpsBooster(vizFpsEnabled)
            end
    
            -- One-time migration to the reference top-right stack layout.
            -- After this first reset, dragging buttons still saves custom positions normally.
            if not _configState["stackSpawnV2"] then
                local migrated = loadConfig()
                for _, bkey in ipairs({"lagSpeed","autoLeft","autoRight","lagCarry","drop","autoBat","carrySpeed","tpBat","tpDown"}) do
                    migrated["btnPos_" .. bkey] = nil
                    _configState["btnPos_" .. bkey] = nil
                end
                _configState["stackSpawnV2"] = true
                saveConfigNow(_configState)
                for key, defaults in pairs(_defaultBtnPositions) do
                    if _fbBtns[key] then
                        _fbBtns[key].Position = UDim2.new(1, defaults.xOff, defaults.yScale, defaults.yOff)
                    end
                end
            end
    
            task.delay(0.5, function()
                local btnKeys = {"lagSpeed","autoLeft","autoRight","lagCarry","drop",
                                 "autoBat","carrySpeed","tpBat","tpDown"}
                for _, bkey in ipairs(btnKeys) do
                    local p = saved["btnPos_" .. bkey]
                    if p and type(p) == "table" and p.xOff ~= nil and p.yOff ~= nil then
                        local btn = _AMIRI._fbBtns and _AMIRI._fbBtns[bkey]
                        if btn then
                            btn.Position = UDim2.new(
                                p.xScale or 0, p.xOff,
                                p.yScale or 0, p.yOff
                            )
                        end
                    end
                end
            end)
        end)
    
        -- Draggable Show Button
        local DragLocked = false
        do
            local _sdn, _sds, _ssp, _sdDragging = false, nil, nil, false
            ShowBtn.InputBegan:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseButton1 and i.UserInputType ~= Enum.UserInputType.Touch then return end
                if DragLocked then return end
                _sdn = true; _sds = i.Position; _ssp = ShowBtn.Position; _sdDragging = false
            end)
            rawConn(UIS.InputEnded, function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseButton1 and i.UserInputType ~= Enum.UserInputType.Touch then return end
                if not _sdn then return end
                _sdn = false
                if _sdDragging then
                    _configState["showBtnPos"] = {
                        xScale = ShowBtn.Position.X.Scale,
                        xOff = ShowBtn.Position.X.Offset,
                        yScale = ShowBtn.Position.Y.Scale,
                        yOff = ShowBtn.Position.Y.Offset,
                    }
                    saveConfigNow(_configState)
                end
                _sdDragging = false
            end)
            ShowBtn.InputChanged:Connect(function(i)
                if not _sdn then return end
                if DragLocked then _sdn = false; return end
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local d = i.Position - _sds
                if not _sdDragging then
                    if math.abs(d.X) > 8 or math.abs(d.Y) > 8 then
                        _sdDragging = true; _showBtnDragged = true
                    else
                        return
                    end
                end
                local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1920, 1080)
                local rawX = _ssp.X.Scale * vp.X + _ssp.X.Offset + d.X
                local rawY = _ssp.Y.Scale * vp.Y + _ssp.Y.Offset + d.Y
                ShowBtn.Position = UDim2.new(0, math.clamp(rawX, 0, vp.X - ShowBtn.AbsoluteSize.X),
                                             0, math.clamp(rawY, 0, vp.Y - ShowBtn.AbsoluteSize.Y))
            end)
