            _toastSub.Position = UDim2.new(0, 12, 0, 24)
            _toastSub.BackgroundTransparency = 1
            _toastSub.Text = ""
            _toastSub.TextColor3 = Color3.fromRGB(200,200,200)
            _toastSub.TextTransparency = 1
            _toastSub.Font = Enum.Font.Gotham
            _toastSub.TextSize = 10
            _toastSub.TextXAlignment = Enum.TextXAlignment.Left
    
            local _toastShowing = false
            local function _showSpike(ms)
                if _toastShowing then return end
                _toastShowing = true
                _toastSub.Text = tostring(ms) .. "ms — high ping detected"
                _toast.Visible = true
                local _ti = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                TS:Create(_toast, _ti, {BackgroundTransparency = 0.08}):Play()
                TS:Create(_toastStroke,_ti, {Transparency = 0.3}):Play()
                TS:Create(_toastTitle, _ti, {TextTransparency = 0}):Play()
                TS:Create(_toastSub, _ti, {TextTransparency = 0}):Play()
                task.delay(2.5, function()
                    local _to = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                    TS:Create(_toast, _to, {BackgroundTransparency = 1}):Play()
                    TS:Create(_toastStroke,_to, {Transparency = 1}):Play()
                    TS:Create(_toastTitle, _to, {TextTransparency = 1}):Play()
                    TS:Create(_toastSub, _to, {TextTransparency = 1}):Play()
                    task.delay(0.45, function()
                        _toast.Visible = false
                        _toastShowing = false
                    end)
                end)
            end
    
            local _lastPing = 0
            rawConn(RunService.Heartbeat, function()
                local ping = 0
                pcall(function()
                    ping = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue())
                end)
                if _AMIRI._infoLabel and _AMIRI._infoLabel.Parent then
                    local clockText = os.date("%I:%M %p"):gsub("^0", "")
                    _AMIRI._infoLabel.Text = string.format(
                        "RAD: %d DUR: %.1fs | %dms | %s",
                        Steal.StealRadius,
                        Steal.StealDuration,
                        ping,
                        clockText
                    )
                end
                if _lastPing > 0 and (ping - _lastPing) >= 100 and ping > 100 then
                    _showSpike(ping)
                end
                _lastPing = ping
            end)
    
            local _lastPct = -1
            rawConn(RunService.Heartbeat, function()
                if not isAlive() then return end
                -- Unified Steal Bar: show progress for whichever steal system is active.
                -- V2 uses _SS2; the normal Auto Steal path uses isStealing/stealStartTime.
                local stealPct = 0
                if _AMIRI._SS2 and _AMIRI._SS2.active then
                    local elapsed = tick() - (_AMIRI._SS2.startTime or tick())
                    stealPct = math.clamp(elapsed / math.max(AG_CONFIG.HOLD_MAX, 0.01), 0, 1)
                elseif isStealing and stealStartTime then
                    local elapsed = tick() - stealStartTime
                    stealPct = math.clamp(elapsed / math.max(Steal.StealDuration, 0.01), 0, 1)
                end
    
                if progressFill and progressFill.Parent then
                    progressFill.Size = UDim2.new(stealPct, 0, 1, 0)
                    progressFill.Visible = true
                end
                if _AMIRI._pctLabel and _AMIRI._pctLabel.Parent then
                    _AMIRI._pctLabel.Text = math.floor(stealPct * 100) .. "%"
                end
    
                -- New Auto Steal progress = Auto Steal only.
                local autoPct = 0
                if isStealing and stealStartTime then
                    autoPct = math.clamp((tick() - stealStartTime) / Steal.StealDuration, 0, 1)
                end
                if _AMIRI._autoProgressFill and _AMIRI._autoProgressFill.Parent then
                    _AMIRI._autoProgressFill.Size = UDim2.new(autoPct, 0, 1, 0)
                end
                if _AMIRI._autoPctLabel and _AMIRI._autoPctLabel.Parent then
                    _AMIRI._autoPctLabel.Text = math.floor(autoPct * 100) .. "% | AUTO STEAL"
                end
            end)
        end)()
    end
    
    -- ============================================================
    -- START THE INTRO, THEN LAUNCH MAIN GUI
    -- ============================================================
    -- PC executor safe launcher: if any optional intro component fails,
    -- the main GUI still starts instead of the whole script dying silently.
    local function _AMIRI_SAFE_START()
        -- PC-safe startup: intro is optional. If the intro or any executor-only
        -- feature fails, launch the main GUI directly. Never hide the real error.
        local started = false
    
        local okIntro, introErr = xpcall(function()
            playIntroAnimation(function()
                if started then return end
                started = true
                local okGui, guiErr = xpcall(startMainGUI, function(e) return tostring(e) end)
                if not okGui then
                    warn("[VISION.GG][PC] Main GUI error: " .. tostring(guiErr))
                end
            end)
        end, function(e) return tostring(e) end)
    
        if not okIntro then
            warn("[VISION.GG][PC] Intro skipped: " .. tostring(introErr))
            if not started then
                started = true
                local okGui, guiErr = xpcall(startMainGUI, function(e) return tostring(e) end)
                if not okGui then
                    warn("[VISION.GG][PC] Main GUI error: " .. tostring(guiErr))
                end
            end
        end
    end
    
    _AMIRI_SAFE_START()
end)